var __index = {"config":{"lang":["ru","en"],"separator":"[\\s\\-]+","pipeline":["stopWordFilter"],"fields":{"title":{"boost":1000.0},"text":{"boost":1.0},"tags":{"boost":1000000.0}}},"docs":[{"location":"index.html","title":"Mergen SDK","text":"<p>\u0410\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u0430\u044f \u0432\u0435\u0440\u0441\u0438\u044f: Android 2.7.1 \u00b7 iOS 2.6.1</p> <p>On-device \u0441\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0438 \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f ID-\u043a\u0430\u0440\u0442 \u041a\u044b\u0440\u0433\u044b\u0437\u0441\u043a\u043e\u0439 \u0420\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0438: \u0434\u0435\u0442\u0435\u043a\u0446\u0438\u044f \u043a\u0430\u0440\u0442\u044b, \u043a\u0440\u043e\u043f \u0441 \u043a\u043e\u0440\u0440\u0435\u043a\u0446\u0438\u0435\u0439 \u043f\u0435\u0440\u0441\u043f\u0435\u043a\u0442\u0438\u0432\u044b, \u0447\u0442\u0435\u043d\u0438\u0435 \u043d\u043e\u043c\u0435\u0440\u0430 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430 \u0438 \u041f\u0418\u041d, MRZ, \u0441\u0432\u0435\u0440\u043a\u0430 \u0434\u0432\u0443\u0445 \u0441\u0442\u043e\u0440\u043e\u043d, \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0438 \u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u044f \u043c\u0430\u043a\u0435\u0442\u0430 (2008 / 2017 / 2025).</p> <p>\u0412\u0435\u0441\u044c \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u043e \u043d\u0430 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435. SDK \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442 \u0441\u0435\u0442\u0435\u0432\u044b\u0445 \u0437\u0430\u043f\u0440\u043e\u0441\u043e\u0432 \u0438 \u043d\u0435 \u0441\u043e\u0431\u0438\u0440\u0430\u0435\u0442 \u0442\u0435\u043b\u0435\u043c\u0435\u0442\u0440\u0438\u044e; \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u043e\u0444\u043b\u0430\u0439\u043d.</p>"},{"location":"index.html#_1","title":"\u0427\u0442\u043e \u043d\u043e\u0432\u043e\u0433\u043e","text":"<ul> <li>2.7.1 (Android) \u2014 hotfix \u0434\u043b\u044f 2.7.0. <code>armeabi-v7a</code> \u0432 2.7.0 \u0441\u043e\u0431\u0438\u0440\u0430\u043b\u0441\u044f \u0438   \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u043b\u0441\u044f, \u043d\u043e \u043f\u0430\u0434\u0430\u043b (<code>SIGBUS</code>) \u043d\u0430 \u043f\u0435\u0440\u0432\u043e\u043c \u0436\u0435 \u043a\u0430\u0434\u0440\u0435 \u2014 \u0438\u0441\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043e. \u0415\u0441\u043b\u0438 \u0432\u044b   \u0443\u0436\u0435 \u043d\u0430 2.7.0, \u043e\u0431\u043d\u043e\u0432\u0438\u0442\u0435\u0441\u044c \u043d\u0430 2.7.1 \u0431\u0435\u0437 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0439 \u0432 \u043a\u043e\u0434\u0435. \u041f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0439 API \u043d\u0435   \u043c\u0435\u043d\u044f\u043b\u0441\u044f.</li> <li>2.7.0 (Android) \u2014 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430 <code>armeabi-v7a</code>: SDK \u0442\u0435\u043f\u0435\u0440\u044c \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0438 \u043d\u0430 32-\u0431\u0438\u0442\u043d\u044b\u0445   ARM-\u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430\u0445, \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 64-\u0431\u0438\u0442\u043d\u044b\u0445. \u041f\u0430\u0439\u043f\u043b\u0430\u0439\u043d \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0432\u0430\u043d\u0438\u044f \u043d\u0435 \u043c\u0435\u043d\u044f\u043b\u0441\u044f \u2014   \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u044b, \u043d\u0435 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u044f. \u041f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0439 API \u043d\u0435 \u043c\u0435\u043d\u044f\u043b\u0441\u044f.</li> <li>2.6.1 \u2014 \u043f\u0440\u0438\u0447\u0438\u043d\u0430 \u043e\u0442\u043a\u0430\u0437\u0430 \u043f\u043e \u0437\u0430\u0441\u043b\u043e\u043d\u0435\u043d\u0438\u044e \u0434\u043b\u044f \u0433\u0430\u043b\u0435\u0440\u0435\u0438: <code>VerifyResult.frontOcclusion</code> /   <code>backOcclusion</code> (<code>finger</code> / <code>shadow</code>) \u2014 \u043f\u043e\u043a\u0430\u0436\u0438\u0442\u0435 \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044e \u00ab\u0443\u0431\u0435\u0440\u0438\u0442\u0435 \u043f\u0430\u043b\u0435\u0446\u00bb, \u0430 \u043d\u0435   \u043e\u0431\u0449\u0438\u0439 \u00ab\u0441\u0442\u043e\u0440\u043e\u043d\u0430 \u043d\u0435 \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u043b\u0430\u0441\u044c\u00bb. \u0410\u0434\u0434\u0438\u0442\u0438\u0432\u043d\u043e, \u043b\u043e\u043c\u0430\u044e\u0449\u0438\u0445 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0439 \u043d\u0435\u0442.</li> <li>2.6.0 \u2014 \u043a\u0430\u0434\u0440-\u0433\u0435\u0439\u0442 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0430: \u043f\u0430\u043b\u0435\u0446 \u043d\u0430 \u0434\u0430\u043d\u043d\u044b\u0445 \u0431\u043b\u043e\u043a\u0438\u0440\u0443\u0435\u0442 \u0437\u0430\u0445\u0432\u0430\u0442 (\u0440\u0430\u043c\u043a\u0430 \u043a\u0440\u0430\u0441\u043d\u0435\u0435\u0442,   \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430 \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0437\u0430\u043a\u0440\u044b\u0442\u043e\u0435 \u043f\u043e\u043b\u0435), \u0430 \u043f\u0435\u0440\u0435\u0432\u0451\u0440\u043d\u0443\u0442\u0430\u044f \u043a\u0430\u0440\u0442\u0430 \u0440\u0430\u0437\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438   \u0434\u043e \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0432\u0430\u043d\u0438\u044f \u2014 \u0440\u044b\u0432\u043e\u043a \u00ab\u0441\u043a\u0430\u043d\u0438\u0440\u0443\u044e-\u043f\u0435\u0440\u0435\u0441\u043d\u0438\u043c\u0430\u044e\u00bb \u043d\u0430 \u043f\u0435\u0440\u0435\u0432\u0451\u0440\u043d\u0443\u0442\u043e\u043c \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0435 \u0443\u0448\u0451\u043b.   \u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0442\u0435\u043d\u0438 \u0438 \u0433\u0440\u044f\u0437\u0438 \u0432 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0442\u0435, \u043d\u043e \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d\u044b \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u2014 \u0441\u043c. \u00ab\u041a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f\u00bb.   \u041b\u043e\u043c\u0430\u044e\u0449\u0435\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e\u0433\u043e API: \u0432 <code>ScanStatus</code> \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d \u043a\u0435\u0439\u0441 <code>Occluded</code> /   <code>.occluded</code> \u2014 \u0438\u0441\u0447\u0435\u0440\u043f\u044b\u0432\u0430\u044e\u0449\u0438\u0435 <code>when</code> / <code>switch</code> \u043d\u0435 \u0441\u043e\u0431\u0435\u0440\u0443\u0442\u0441\u044f \u0431\u0435\u0437 \u043d\u043e\u0432\u043e\u0439 \u0432\u0435\u0442\u043a\u0438,   \u043c\u0438\u0433\u0440\u0430\u0446\u0438\u044f \u0432 \u00ab\u0421\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f \u0438 \u0441\u043e\u0431\u044b\u0442\u0438\u044f\u00bb.</li> <li>2.5.2 \u2014 \u0442\u0438\u043f\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0441\u0442\u0430\u0442\u0443\u0441 \u043a\u0430\u0434\u0440\u0430 <code>ScanStatus</code> (\u043c\u0430\u0448\u0438\u043d\u043e\u0447\u0438\u0442\u0430\u0435\u043c\u044b\u0439 \u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442   \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0438, \u043a\u043e\u0442\u043e\u0440\u0443\u044e SDK \u043f\u043e\u043a\u0430\u0437\u0430\u043b \u0431\u044b \u0441\u0430\u043c) \u2014 \u043c\u043e\u0436\u043d\u043e \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u043f\u0435\u0440\u0435\u0439\u0442\u0438 \u043d\u0430 \u0441\u0432\u043e\u0438 \u0442\u0435\u043a\u0441\u0442\u044b;   \u0444\u043e\u043d\u0430\u0440\u0438\u043a \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u043c \u043d\u0430 drop-in-\u044d\u043a\u0440\u0430\u043d\u0430\u0445; \u043d\u0430 iOS \u043f\u043e\u043a\u0430\u0434\u0440\u043e\u0432\u044b\u0439 \u043a\u043e\u043b\u0431\u044d\u043a \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f   <code>onFrameState</code>.</li> <li>2.5.1 \u2014 \u043c\u043d\u043e\u0433\u043e\u043a\u0430\u0434\u0440\u043e\u0432\u043e\u0435 \u043d\u0430\u043a\u043e\u043f\u043b\u0435\u043d\u0438\u0435 \u0432\u043a\u043b\u044e\u0447\u0435\u043d\u043e \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e (\u043d\u0430\u0434\u0451\u0436\u043d\u0435\u0435 \u0447\u0442\u0435\u043d\u0438\u0435);   \u0430\u043d\u0442\u0438-\u043e\u0442\u043b\u0430\u0434\u043e\u0447\u043d\u0430\u044f \u0437\u0430\u0449\u0438\u0442\u0430 \u043f\u043e\u0434 \u043e\u0442\u043b\u0430\u0434\u0447\u0438\u043a\u043e\u043c \u043d\u0435 \u043f\u0440\u0435\u0440\u044b\u0432\u0430\u0435\u0442 \u0440\u0430\u0431\u043e\u0442\u0443, \u0430 \u0442\u0438\u0445\u043e \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442.   \u041f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0439 API \u043d\u0435 \u043c\u0435\u043d\u044f\u043b\u0441\u044f.</li> <li>2.5.0 \u2014 \u043d\u043e\u0432\u044b\u0439 \u043a\u043e\u043c\u043f\u0430\u043a\u0442\u043d\u044b\u0439 MRZ-\u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0432\u0430\u0442\u0435\u043b\u044c (\u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0431\u044b\u0441\u0442\u0440\u0435\u0435 \u0438 \u043b\u0435\u0433\u0447\u0435 \u043f\u0440\u0435\u0436\u043d\u0435\u0433\u043e)   \u0438 \u043c\u043d\u043e\u0433\u043e\u043f\u0440\u043e\u0445\u043e\u0434\u043d\u043e\u0435 \u0433\u043e\u043b\u043e\u0441\u043e\u0432\u0430\u043d\u0438\u0435 \u0447\u0442\u0435\u043d\u0438\u0439. \u041f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0439 API \u043d\u0435 \u043c\u0435\u043d\u044f\u043b\u0441\u044f.</li> <li>2.4.0 \u2014 <code>deferBackMrz</code>: \u0447\u0442\u0435\u043d\u0438\u0435 MRZ \u043e\u0431\u043e\u0440\u043e\u0442\u0430 \u0432\u044b\u043d\u043e\u0441\u0438\u0442\u0441\u044f \u0437\u0430 \u043f\u0440\u0435\u0434\u0435\u043b\u044b \u043e\u043a\u043d\u0430 \u043a\u0430\u043c\u0435\u0440\u044b \u2014   \u0441\u043a\u0430\u043d \u043e\u0431\u043e\u0440\u043e\u0442\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442\u0441\u044f \u0442\u0430\u043a \u0436\u0435 \u0431\u044b\u0441\u0442\u0440\u043e, \u043a\u0430\u043a \u043b\u0438\u0446\u0435\u0432\u043e\u0439. \u041c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u0430\u044f \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430   iOS-\u043f\u0430\u043a\u0435\u0442\u0430 \u0441\u043d\u0438\u0436\u0435\u043d\u0430 \u0434\u043e iOS 15.</li> </ul>"},{"location":"index.html#_2","title":"\u0422\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f","text":"iOSAndroid \u0412\u0435\u0440\u0441\u0438\u044f SDK 2.6.1 (\u0432\u0435\u0440\u0441\u0438\u0438 2.3.x \u0438 \u0441\u0442\u0430\u0440\u0448\u0435 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043b\u0438 iOS 16 \u2014 \u043d\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c) \u041f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430 iOS 15+ \u0423\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430 arm64, iPhone 8 / X \u0438 \u043d\u043e\u0432\u0435\u0435 \u0421\u0438\u043c\u0443\u043b\u044f\u0442\u043e\u0440 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0434\u043b\u044f \u0441\u0431\u043e\u0440\u043a\u0438; \u043f\u043e\u043b\u043d\u044b\u0439 \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d \u0442\u0435\u0441\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043d\u0430 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435 \u0420\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u044f <code>NSCameraUsageDescription</code> \u0432 Info.plist \u0412\u0435\u0440\u0441\u0438\u044f SDK 2.7.1 \u041f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430 minSdk 24 (Android 7.0+) \u0423\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430 ARM, 32- \u0438 64-\u0431\u0438\u0442\u043d\u044b\u0435 (<code>armeabi-v7a</code>, <code>arm64-v8a</code>) \u0420\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u044f <code>CAMERA</code> (\u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u0430 \u0432 \u043c\u0430\u043d\u0438\u0444\u0435\u0441\u0442\u0435 SDK; runtime-\u0437\u0430\u043f\u0440\u043e\u0441 \u2014 \u043d\u0430 \u0441\u0442\u043e\u0440\u043e\u043d\u0435 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f)"},{"location":"index.html#_3","title":"\u0422\u0438\u043f\u043e\u0432\u044b\u0435 \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0438","text":"\u0421\u0446\u0435\u043d\u0430\u0440\u0438\u0439 iOS Android \u0421\u043a\u0430\u043d \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u043a\u0430\u043c\u0435\u0440\u043e\u0439 <code>MergenScanView</code> \u2192 <code>MergenScanResult</code> <code>MergenScanView</code> \u2192 <code>MergenScanResult</code> \u0412\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u0434\u0432\u0443\u0445 \u0441\u0442\u043e\u0440\u043e\u043d <code>MergenSDK.verify(front:back:license:)</code> <code>Mergen.verify(context, front, back, license)</code> \u0412\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u043f\u043e \u0444\u043e\u0442\u043e \u0438\u0437 \u0433\u0430\u043b\u0435\u0440\u0435\u0438 \u0442\u043e\u0442 \u0436\u0435 <code>verify</code>, \u0432\u0445\u043e\u0434 <code>.image(...)</code> \u0442\u043e\u0442 \u0436\u0435 <code>verify</code>, \u0432\u0445\u043e\u0434 <code>MergenSideInput.Image(...)</code> <p>\u0420\u0430\u0437\u043d\u0438\u0446\u044b \u043c\u0435\u0436\u0434\u0443 \u00ab\u0441\u043a\u0430\u043d\u043e\u043c \u043a\u0430\u043c\u0435\u0440\u043e\u0439\u00bb \u0438 \u00ab\u0444\u043e\u0442\u043e \u0438\u0437 \u0433\u0430\u043b\u0435\u0440\u0435\u0438\u00bb \u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u0432\u044b\u0437\u043e\u0432\u0430 \u043d\u0435\u0442 \u2014 \u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0442\u0438\u043f \u0432\u0445\u043e\u0434\u0430. SDK \u0441\u0430\u043c \u0432\u044b\u0431\u0438\u0440\u0430\u0435\u0442 \u0431\u044b\u0441\u0442\u0440\u044b\u0439 \u043f\u0443\u0442\u044c (\u0433\u043e\u0442\u043e\u0432\u044b\u0439 \u0441\u043d\u0438\u043c\u043e\u043a \u0441\u0442\u043e\u0440\u043e\u043d\u044b, ~1 \u043c\u0441) \u0438\u043b\u0438 \u043f\u043e\u043b\u043d\u044b\u0439 OCR-\u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d (\u0441\u044b\u0440\u043e\u0435 \u0444\u043e\u0442\u043e).</p> <p>\u0412\u043e\u043f\u0440\u043e\u0441\u044b \u043f\u043e SDK, \u0432\u044b\u0434\u0430\u0447\u0430 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0439 \u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u043e\u0432 \u2014 \u043a \u043f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a\u0443 Mergen.</p>"},{"location":"config.html","title":"\u041a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f","text":"<p>\u041f\u043e\u043b\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432 \u0434\u0432\u0438\u0436\u043a\u0430 \u0438 \u043a\u0430\u043c\u0435\u0440\u044b \u2014 <code>MergenScannerConfig</code>. \u041f\u0435\u0440\u0435\u0434\u0430\u0451\u0442\u0441\u044f \u0432 <code>MergenScannerView</code> / headless-\u0445\u044d\u043d\u0434\u043b; \u0443 <code>MergenScanView</code> \u0445\u043e\u0434\u043e\u0432\u044b\u0435 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u0432\u044b\u043d\u0435\u0441\u0435\u043d\u044b \u0432 \u0441\u0438\u0433\u043d\u0430\u0442\u0443\u0440\u0443 (iOS \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u0432\u0435\u0441\u044c \u043a\u043e\u043d\u0444\u0438\u0433 \u0447\u0435\u0440\u0435\u0437 <code>configuration:</code>).</p> <p>\u0413\u043e\u0442\u043e\u0432\u044b\u0435 \u043f\u0440\u0435\u0441\u0435\u0442\u044b \u043f\u043e\u0440\u043e\u0433\u043e\u0432: <code>strict</code> (0.65 / 0.80 / 8 \u043a\u0430\u0434\u0440\u043e\u0432) \u0438 <code>relaxed</code> (0.40 / 0.55 / 3).</p>"},{"location":"config.html#_2","title":"\u0421\u0431\u043e\u0440\u043a\u0430","text":"iOSAndroid <pre><code>let config = MergenScannerConfig {\n    $0.enforceSideMatch = true\n    $0.expectedSide     = .front\n    $0.liveVersionProbe = true\n    $0.scanSpeed        = .normal\n}\n</code></pre> <pre><code>val config = MergenScannerConfig(\n    sideGate         = SideGateConfig.frontOnly(),\n    liveVersionProbe = true,\n    scanSpeed        = ScanSpeed.NORMAL,\n)\n</code></pre>"},{"location":"config.html#_3","title":"\u041e\u0431\u0449\u0438\u0435 \u043f\u043e\u043b\u044f (\u043e\u0431\u0435 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u044b)","text":"\u041f\u043e\u043b\u0435 \u0414\u0435\u0444\u043e\u043b\u0442 \u0427\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 <code>detectionThreshold</code> 0.5 \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u0430\u044f \u0443\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u0434\u0435\u0442\u0435\u043a\u0446\u0438\u0438, \u0447\u0442\u043e\u0431\u044b \u0441\u0447\u0438\u0442\u0430\u0442\u044c \u043a\u0430\u0440\u0442\u0443 \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0435\u043d\u043d\u043e\u0439 <code>qualityThreshold</code> 0.7 \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0431\u0430\u043b\u043b \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0430 \u043a\u0430\u0434\u0440\u0430 \u0434\u043b\u044f \u0437\u0430\u0445\u0432\u0430\u0442\u0430 <code>stabilityFrames</code> iOS 5 / Android 3 \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043f\u043e\u0434\u0440\u044f\u0434 \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u044b\u0445 \u043a\u0430\u0434\u0440\u043e\u0432 \u043d\u0443\u0436\u043d\u043e \u0434\u043e \u0437\u0430\u0445\u0432\u0430\u0442\u0430 <code>scanSpeed</code> <code>nil</code> \u043f\u0440\u0435\u0441\u0435\u0442 \u043f\u043e\u0432\u0435\u0440\u0445 <code>stabilityFrames</code>: <code>fast</code> (2) / <code>normal</code> (3) / <code>thorough</code> (5) <code>autoCapture</code> (<code>enableAutoCapture</code>) <code>true</code> \u0430\u0432\u0442\u043e\u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0438\u0435 \u043f\u0440\u0438 \u0434\u043e\u0441\u0442\u0438\u0436\u0435\u043d\u0438\u0438 \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u0438 <code>licenseKey</code> <code>nil</code> \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u044f JSON-\u0441\u0442\u0440\u043e\u043a\u043e\u0439; \u043f\u0440\u0438 <code>nil</code> \u2014 <code>license.json</code> \u0438\u0437 \u0431\u0430\u043d\u0434\u043b\u0430/assets <code>leanIdentityFields</code> <code>true</code> \u0447\u0438\u0442\u0430\u0442\u044c \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u043e\u043c\u0435\u0440, \u041f\u0418\u041d \u0438 MRZ (\u043f\u0440\u043e\u0434\u0430\u043a\u0448\u0435\u043d-\u0440\u0435\u0436\u0438\u043c); <code>false</code> \u2014 \u043f\u043e\u043b\u043d\u044b\u0439 OCR \u0432\u0441\u0435\u0445 \u043f\u043e\u043b\u0435\u0439 <code>autofocusEnabled</code> <code>true</code> \u0442\u043e\u0447\u0435\u0447\u043d\u044b\u0435 AF-\u0442\u0440\u0438\u0433\u0433\u0435\u0440\u044b \u043e\u0442 SDK; <code>false</code> \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u044b\u0439 AF \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u044b <code>useStillCapture</code> <code>true</code> \u043f\u0440\u0438 \u043d\u0435\u0441\u0445\u043e\u0434\u044f\u0449\u0435\u043c\u0441\u044f \u0437\u0430\u0445\u0432\u0430\u0442\u0435 \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u043e\u0434\u0438\u043d \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0438\u0439 \u0441\u043d\u0438\u043c\u043e\u043a \u0438 \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0442\u044c \u043f\u043e \u043d\u0435\u043c\u0443 <code>liveVersionProbe</code> <code>false</code> \u043a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u0432\u0435\u0440\u0441\u0438\u0438 \u043d\u0430 \u043a\u0430\u0436\u0434\u043e\u043c \u043a\u0430\u0434\u0440\u0435 \u2014 \u043c\u0433\u043d\u043e\u0432\u0435\u043d\u043d\u0430\u044f \u043a\u0440\u0430\u0441\u043d\u0430\u044f \u0440\u0430\u043c\u043a\u0430 \u043d\u0430 \u00ab\u043d\u0435 \u0442\u043e\u0439\u00bb \u0441\u0442\u043e\u0440\u043e\u043d\u0435 <code>liveVersionProbeConf</code> 0.65 \u043f\u043e\u0440\u043e\u0433 \u0443\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u043f\u0440\u043e\u0431\u043d\u0438\u043a\u0430 (0.20\u20261.0); \u043d\u0438\u0436\u0435 \u2014 \u0433\u0435\u0439\u0442 \u043d\u0435\u0439\u0442\u0440\u0430\u043b\u0435\u043d <code>showCaptureTips</code> (<code>showCaptureHints</code>) <code>true</code> \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0438 \u00ab\u043f\u043e\u0434\u043d\u0435\u0441\u0438\u0442\u0435 \u0431\u043b\u0438\u0436\u0435 / \u043e\u0442\u043e\u0434\u0432\u0438\u043d\u044c\u0442\u0435 / \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u0442\u0435\u043c\u043d\u043e / \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u044f\u0440\u043a\u043e\u00bb. \u041f\u0440\u0438\u0447\u0438\u043d\u0443 \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0433\u043e \u0437\u0430\u0445\u0432\u0430\u0442\u0430 \u043d\u0435 \u0433\u0430\u0441\u0438\u0442: \u043a\u0440\u0430\u0441\u043d\u0430\u044f \u0440\u0430\u043c\u043a\u0430 \u0438 \u0441\u0442\u0430\u0442\u0443\u0441 <code>Occluded</code> \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u0432 \u043b\u044e\u0431\u043e\u043c \u0441\u043b\u0443\u0447\u0430\u0435 (\u0442\u0435\u043a\u0441\u0442 \u00ab\u0423\u0431\u0435\u0440\u0438\u0442\u0435 \u043f\u0430\u043b\u0435\u0446 \u0441 \u2026\u00bb \u043d\u0430 iOS \u0442\u043e\u0436\u0435 \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f, \u043d\u0430 Android \u2014 \u0433\u0430\u0441\u043d\u0435\u0442) <code>autoTorch</code> <code>true</code> \u0430\u0432\u0442\u043e-\u0444\u043e\u043d\u0430\u0440\u0438\u043a \u043f\u043e\u0441\u043b\u0435 \u0441\u0435\u0440\u0438\u0438 \u0442\u0451\u043c\u043d\u044b\u0445 \u043a\u0430\u0434\u0440\u043e\u0432; \u0440\u0443\u0447\u043d\u043e\u0439 <code>setFlashlightEnabled</code> \u0432\u0441\u0435\u0433\u0434\u0430 \u043f\u0440\u0438\u043e\u0440\u0438\u0442\u0435\u0442\u043d\u0435\u0435 <code>scanRoi</code> <code>nil</code> \u0441\u0443\u0436\u0435\u043d\u0438\u0435 \u0437\u043e\u043d\u044b \u0441\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f (\u043a\u0430\u0434\u0440 \u043e\u0431\u0440\u0435\u0437\u0430\u0435\u0442\u0441\u044f \u0434\u043e \u0434\u0435\u0442\u0435\u043a\u0446\u0438\u0438); \u26a0\ufe0f \u043e\u0441\u0438 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c \u0440\u0430\u0437\u043b\u0438\u0447\u0430\u044e\u0442\u0441\u044f \u2014 \u0441\u043c. \u00ab\u0421\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435\u00bb <code>handlePermissionsInternally</code> <code>true</code> <code>false</code> \u2014 SDK \u043d\u0435 \u0437\u0430\u043f\u0440\u0430\u0448\u0438\u0432\u0430\u0435\u0442 \u043a\u0430\u043c\u0435\u0440\u0443 \u0441\u0430\u043c, \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 \u043e\u0431 \u043e\u0442\u043a\u0430\u0437\u0435 <code>useUnifiedDetector</code> <code>true</code> \u0435\u0434\u0438\u043d\u044b\u0439 \u043f\u0440\u043e\u0445\u043e\u0434 \u00ab\u0434\u0435\u0442\u0435\u043a\u0446\u0438\u044f + \u043a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u0441\u0442\u043e\u0440\u043e\u043d\u044b\u00bb <code>deferBackMrz</code> <code>false</code> MRZ \u043e\u0431\u043e\u0440\u043e\u0442\u0430 \u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u043f\u043e\u0441\u043b\u0435 \u0437\u0430\u0445\u0432\u0430\u0442\u0430 (\u043d\u0430 \u044d\u0442\u0430\u043f\u0435 <code>verify</code> \u043f\u043e \u043a\u0440\u043e\u043f\u0443), \u0430 \u043d\u0435 \u0432 \u043e\u043a\u043d\u0435 \u043a\u0430\u043c\u0435\u0440\u044b \u2014 \u0441\u043a\u0430\u043d \u043e\u0431\u043e\u0440\u043e\u0442\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442\u0441\u044f \u0441\u043e \u0441\u043a\u043e\u0440\u043e\u0441\u0442\u044c\u044e \u043b\u0438\u0446\u0435\u0432\u043e\u0433\u043e. \u0412\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0435 verify-\u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0438 \u0432\u043a\u043b\u044e\u0447\u0430\u044e\u0442 \u0441\u0430\u043c\u0438; \u0432 \u0433\u0430\u043b\u0435\u0440\u0435\u0439\u043d\u043e\u043c \u043f\u0443\u0442\u0438 \u043d\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442; \u0432 \u0440\u0435\u0436\u0438\u043c\u0435 \u00ab\u0442\u043e\u043b\u044c\u043a\u043e \u0441\u043a\u0430\u043d\u0435\u0440 \u0431\u0435\u0437 verify\u00bb \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0430\u0439\u0442\u0435 \u2014 <code>mrz</code>/<code>pin</code> \u043e\u0431\u043e\u0440\u043e\u0442\u0430 \u0431\u0443\u0434\u0443\u0442 \u043f\u0443\u0441\u0442\u044b\u043c\u0438"},{"location":"config.html#side-gate","title":"Side-gate: \u00ab\u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0442\u044c \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0443\u0436\u043d\u0443\u044e \u0441\u0442\u043e\u0440\u043e\u043d\u0443\u00bb","text":"<p>\u041e\u0442\u043a\u043b\u043e\u043d\u0451\u043d\u043d\u044b\u0439 \u0437\u0430\u0445\u0432\u0430\u0442 \u043d\u0435 \u043f\u043e\u043f\u0430\u0434\u0430\u0435\u0442 \u0432 <code>onResult</code>/<code>onFinished</code> \u2014 \u0440\u0430\u043c\u043a\u0430 \u043a\u043e\u0440\u043e\u0442\u043a\u043e \u043a\u0440\u0430\u0441\u043d\u0435\u0435\u0442 \u0438 \u0441\u043a\u0430\u043d \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442\u0441\u044f.</p> iOSAndroid <pre><code>$0.enforceSideMatch   = true\n$0.expectedSide       = .front        // .any / .front / .back\n$0.expectedGeneration = \"2017\"        // \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e: \"2008\" | \"2017\" | \"2025\"\n</code></pre> <pre><code>sideGate = SideGateConfig.frontOnly()          // \u0442\u043e\u043b\u044c\u043a\u043e \u043b\u0438\u0446\u0435\u0432\u0430\u044f\nsideGate = SideGateConfig.backOnly()           // \u0442\u043e\u043b\u044c\u043a\u043e \u043e\u0431\u043e\u0440\u043e\u0442\nsideGate = SideGateConfig.front(\"2017\")        // \u043b\u0438\u0446\u0435\u0432\u0430\u044f \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e\u0433\u043e \u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u044f\nsideGate = SideGateConfig.back(\"2025\")\n// \u0438\u043b\u0438 \u044f\u0432\u043d\u043e: SideGateConfig(enabled = true, expectedSide = ExpectedSide.FRONT,\n//                          expectedGeneration = null)\n</code></pre>"},{"location":"config.html#frame-gate","title":"\u041a\u0430\u0434\u0440-\u0433\u0435\u0439\u0442: \u043f\u0430\u043b\u0435\u0446, \u0442\u0435\u043d\u044c, \u0433\u0440\u044f\u0437\u044c","text":"<p>\u041f\u0435\u0440\u0435\u0434 \u043a\u0430\u0436\u0434\u043e\u0439 \u043f\u043e\u043f\u044b\u0442\u043a\u043e\u0439 \u0437\u0430\u0445\u0432\u0430\u0442\u0430 \u2014 \u0438 \u0440\u0430\u0437 \u0432 350 \u043c\u0441 \u0432\u043e \u0432\u0440\u0435\u043c\u044f \u043d\u0430\u0432\u0435\u0434\u0435\u043d\u0438\u044f \u2014 SDK \u043f\u0440\u043e\u0433\u043e\u043d\u044f\u0435\u0442 \u043f\u043e \u0432\u044b\u043f\u0440\u044f\u043c\u043b\u0435\u043d\u043d\u043e\u043c\u0443 \u043a\u0440\u043e\u043f\u0443 \u043a\u0430\u0440\u0442\u044b \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0443\u044e \u043c\u043e\u0434\u0435\u043b\u044c \u043a\u0430\u0434\u0440-\u0433\u0435\u0439\u0442\u0430. \u041e\u043d\u0430 \u0440\u0430\u0437\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442 \u043f\u0435\u0440\u0435\u0432\u0451\u0440\u043d\u0443\u0442\u0443\u044e \u043a\u0430\u0440\u0442\u0443 \u0434\u043e \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0432\u0430\u043d\u0438\u044f \u0438 \u0431\u043b\u043e\u043a\u0438\u0440\u0443\u0435\u0442 \u0437\u0430\u0445\u0432\u0430\u0442, \u043a\u043e\u0433\u0434\u0430 \u043d\u0430 \u0434\u0430\u043d\u043d\u044b\u0445 \u043b\u0435\u0436\u0438\u0442 \u043f\u0430\u043b\u0435\u0446 (\u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u0438 \u0442\u0435\u043a\u0441\u0442\u044b \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043e\u043a \u2014 \u0432 \u0440\u0430\u0437\u0434\u0435\u043b\u0435 \u00ab\u0421\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435\u00bb).</p> <p>\u041c\u043e\u0434\u0435\u043b\u044c \u0432\u0445\u043e\u0434\u0438\u0442 \u0432 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0442 SDK (\u22482.8 \u041c\u0411), \u0434\u043e\u0431\u0430\u0432\u043b\u044f\u0442\u044c \u0432 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043d\u0443\u0436\u043d\u043e. \u0417\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u0430\u043d\u044b \u043d\u0430 \u0431\u043e\u0435\u0432\u0443\u044e \u0441\u044a\u0451\u043c\u043a\u0443 \u0438 \u0432 \u043e\u0431\u044b\u0447\u043d\u043e\u0439 \u0438\u043d\u0442\u0435\u0433\u0440\u0430\u0446\u0438\u0438 \u043d\u0435 \u043c\u0435\u043d\u044f\u044e\u0442\u0441\u044f:</p> \u041a\u043b\u044e\u0447 \u0414\u0435\u0444\u043e\u043b\u0442 \u0427\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 <code>enable_quality_gate</code> <code>true</code> \u043a\u0430\u0434\u0440-\u0433\u0435\u0439\u0442 \u0446\u0435\u043b\u0438\u043a\u043e\u043c; <code>false</code> \u2014 \u043c\u043e\u0434\u0435\u043b\u044c \u043d\u0435 \u0437\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u0442\u0441\u044f \u0438 \u043d\u0435 \u043e\u043f\u0440\u0430\u0448\u0438\u0432\u0430\u0435\u0442\u0441\u044f <code>quality_gate_auto_rotate</code> <code>true</code> \u0430\u0432\u0442\u043e-\u0440\u0430\u0437\u0432\u043e\u0440\u043e\u0442 \u043f\u0435\u0440\u0435\u0432\u0451\u0440\u043d\u0443\u0442\u043e\u0439 \u043a\u0430\u0440\u0442\u044b \u0434\u043e \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0432\u0430\u043d\u0438\u044f <code>quality_gate_finger_threshold</code> <code>0.99</code> \u043f\u043e\u0440\u043e\u0433 \u00ab\u043f\u0430\u043b\u0435\u0446 \u043d\u0430 \u0434\u0430\u043d\u043d\u044b\u0445\u00bb; \u043f\u0440\u0438 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0438 \u0437\u0430\u0445\u0432\u0430\u0442 \u0431\u043b\u043e\u043a\u0438\u0440\u0443\u0435\u0442\u0441\u044f. \u0417\u043d\u0430\u0447\u0435\u043d\u0438\u0435 &gt; 1.0 \u0432\u044b\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0443 <code>quality_gate_shadow_threshold</code> <code>1.1</code> \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d\u043e (1.1 &gt; 1.0 \u2014 \u043d\u0435 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442 \u043d\u0438\u043a\u043e\u0433\u0434\u0430), \u0441\u043c. \u043f\u0440\u0435\u0434\u0443\u043f\u0440\u0435\u0436\u0434\u0435\u043d\u0438\u0435 \u043d\u0438\u0436\u0435 <code>quality_gate_dirt_threshold</code> <code>1.1</code> \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d\u043e (1.1 &gt; 1.0 \u2014 \u043d\u0435 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442 \u043d\u0438\u043a\u043e\u0433\u0434\u0430), \u0441\u043c. \u043f\u0440\u0435\u0434\u0443\u043f\u0440\u0435\u0436\u0434\u0435\u043d\u0438\u0435 \u043d\u0438\u0436\u0435 <code>quality_gate_field_coverage</code> <code>0.25</code> \u043a\u0430\u043a\u0443\u044e \u0434\u043e\u043b\u044e \u043f\u043b\u043e\u0449\u0430\u0434\u0438 \u043f\u043e\u043b\u044f \u0434\u043e\u043b\u0436\u043d\u0430 \u0437\u0430\u043a\u0440\u044b\u0432\u0430\u0442\u044c \u043f\u043e\u043c\u0435\u0445\u0430, \u0447\u0442\u043e\u0431\u044b \u043f\u043e\u043b\u0435 \u0431\u044b\u043b\u043e \u043d\u0430\u0437\u0432\u0430\u043d\u043e \u0432 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0435 <code>quality_gate_probe_interval_ms</code> <code>350</code> \u043a\u0430\u043a \u0447\u0430\u0441\u0442\u043e \u043e\u043f\u0440\u0430\u0448\u0438\u0432\u0430\u0442\u044c \u043c\u043e\u0434\u0435\u043b\u044c \u0432\u043e \u0432\u0440\u0435\u043c\u044f \u043d\u0430\u0432\u0435\u0434\u0435\u043d\u0438\u044f; <code>0</code> \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u043c\u043e\u043c\u0435\u043d\u0442 \u043f\u043e\u043f\u044b\u0442\u043a\u0438 \u0437\u0430\u0445\u0432\u0430\u0442\u0430 <code>quality_gate_block_timeout_ms</code> <code>20000</code> \u043f\u0440\u0435\u0434\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u0435\u043b\u044c: \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u0430\u044f \u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u043a\u0430 \u0434\u043e\u043b\u044c\u0448\u0435 \u044d\u0442\u043e\u0433\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0441\u043d\u0438\u043c\u0430\u0435\u0442\u0441\u044f, \u0447\u0442\u043e\u0431\u044b \u043a\u0430\u043c\u0435\u0440\u0430 \u043d\u0435 \u00ab\u0437\u0430\u0432\u0438\u0441\u043b\u0430\u00bb <p>\u0422\u0435\u043d\u044c \u0438 \u0433\u0440\u044f\u0437\u044c \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d\u044b \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u2014 \u043e\u0441\u043e\u0437\u043d\u0430\u043d\u043d\u043e</p> <p>\u0422\u0435\u043d\u044c. \u041f\u043e\u0440\u043e\u0433 \u043e\u0442\u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u0430\u043d \u043d\u0430 \u0441\u0442\u0430\u0442\u0438\u0447\u043d\u044b\u0445 \u043a\u0440\u043e\u043f\u0430\u0445 \u0438 \u043d\u0435 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u0442\u0441\u044f \u043d\u0430 \u0436\u0438\u0432\u0443\u044e \u0441\u044a\u0451\u043c\u043a\u0443: \u043f\u0440\u0438 \u043d\u0430\u0432\u0435\u0434\u0435\u043d\u0438\u0438 \u0442\u0435\u043b\u0435\u0444\u043e\u043d \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u043d\u0430\u0434 \u043a\u0430\u0440\u0442\u043e\u0439 \u0438 \u0441\u0430\u043c \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442 \u043d\u0430 \u043d\u0435\u0451 \u0442\u0435\u043d\u044c. \u0412 \u043f\u043e\u043b\u0435 \u044d\u0442\u043e \u0434\u0430\u0432\u0430\u043b\u043e \u043b\u043e\u0436\u043d\u044b\u0435 \u00ab\u0423\u0431\u0435\u0440\u0438\u0442\u0435 \u0442\u0435\u043d\u044c\u00bb \u043d\u0430 \u043a\u0430\u0434\u0440\u0430\u0445, \u0441 \u043a\u043e\u0442\u043e\u0440\u044b\u043c\u0438 \u0432\u0441\u0451 \u0432 \u043f\u043e\u0440\u044f\u0434\u043a\u0435. \u0421\u0430\u043c\u0430 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0432 \u043c\u043e\u0434\u0435\u043b\u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0430, \u043d\u043e \u0435\u0451 \u043f\u043e\u0440\u043e\u0433 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442 \u00ab\u043d\u0438\u043a\u043e\u0433\u0434\u0430\u00bb.</p> <p>\u0413\u0440\u044f\u0437\u044c. \u041d\u0430 \u0447\u0435\u0441\u0442\u043d\u043e\u0439 \u0432\u044b\u0431\u043e\u0440\u043a\u0435 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0445 \u0437\u0430\u0433\u0440\u044f\u0437\u043d\u0435\u043d\u0438\u0439 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043d\u0430\u0445\u043e\u0434\u0438\u0442 \u043b\u0438\u0448\u044c 30 % \u043f\u044f\u0442\u0435\u043d \u043f\u0440\u0438 \u0442\u0440\u0435\u0431\u0443\u0435\u043c\u044b\u0445 90 % \u2014 \u0433\u0435\u0439\u0442 \u043f\u0440\u0438\u0451\u043c\u043a\u0438 \u043d\u0435 \u043f\u0440\u043e\u0439\u0434\u0435\u043d. \u0412\u0434\u043e\u0431\u0430\u0432\u043e\u043a \u043c\u0430\u0441\u043a\u0430 \u043d\u0435 \u043b\u043e\u043a\u0430\u043b\u0438\u0437\u0443\u0435\u0442 \u0433\u0440\u044f\u0437\u044c, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u00ab\u0433\u0440\u044f\u0437\u044c \u0437\u0430\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u043f\u043e\u043b\u0435 N\u00bb SDK \u043d\u0435 \u043e\u0442\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442 \u0432 \u043f\u0440\u0438\u043d\u0446\u0438\u043f\u0435.</p> <p>\u041e\u0431\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u043e\u0441\u0442\u0430\u043d\u0443\u0442\u0441\u044f \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d\u043d\u044b\u043c\u0438, \u043f\u043e\u043a\u0430 \u043d\u0435 \u043f\u043e\u044f\u0432\u044f\u0442\u0441\u044f \u0434\u0430\u043d\u043d\u044b\u0435, \u043d\u0430 \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u0438\u0445 \u043c\u043e\u0436\u043d\u043e \u0447\u0435\u0441\u0442\u043d\u043e \u043e\u0442\u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u0430\u0442\u044c. \u0412\u043a\u043b\u044e\u0447\u0430\u0442\u044c \u0438\u0445 \u00ab\u043d\u0430 \u0432\u0441\u044f\u043a\u0438\u0439 \u0441\u043b\u0443\u0447\u0430\u0439\u00bb \u043d\u0435 \u043d\u0443\u0436\u043d\u043e: \u043b\u043e\u0436\u043d\u043e\u0435 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0435 \u0437\u0434\u0435\u0441\u044c \u0441\u0442\u043e\u0438\u0442 \u0434\u043e\u0440\u043e\u0436\u0435 \u043f\u0440\u043e\u043f\u0443\u0441\u043a\u0430 \u2014 \u043e\u043d\u043e \u043d\u0435 \u0434\u0430\u0451\u0442 \u043e\u0442\u0441\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442.</p> <p>\u0413\u0434\u0435 \u0437\u0430\u0434\u0430\u044e\u0442\u0441\u044f</p> <p>\u042d\u0442\u043e \u043a\u043b\u044e\u0447\u0438 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438 \u0434\u0432\u0438\u0436\u043a\u0430, \u0430 \u043d\u0435 \u043f\u043e\u043b\u044f <code>MergenScannerConfig</code>. \u041d\u0430 drop-in-\u044d\u043a\u0440\u0430\u043d\u0430\u0445 \u043e\u0431\u0435\u0438\u0445 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u0438\u0437 \u0442\u0430\u0431\u043b\u0438\u0446\u044b: \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f, \u043a\u043e\u0442\u043e\u0440\u0443\u044e SDK \u0441\u043e\u0431\u0438\u0440\u0430\u0435\u0442 \u0438\u0437 <code>MergenScannerConfig</code>, \u043f\u0435\u0440\u0435\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u0444\u0430\u0439\u043b <code>config.json</code> \u0446\u0435\u043b\u0438\u043a\u043e\u043c. \u0415\u0441\u043b\u0438 \u0432\u0430\u0448\u0435\u043c\u0443 \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u044e \u0441\u044a\u0451\u043c\u043a\u0438 \u043d\u0443\u0436\u043d\u044b \u0434\u0440\u0443\u0433\u0438\u0435 \u043f\u043e\u0440\u043e\u0433\u0438 \u2014 \u0441\u043e\u0433\u043b\u0430\u0441\u0443\u0439\u0442\u0435 \u0438\u0445 \u0441 \u043f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a\u043e\u043c, \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u043e\u0442\u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u0430\u043d\u044b \u043d\u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0445 \u043a\u0430\u0434\u0440\u0430\u0445.</p>"},{"location":"config.html#ios","title":"\u0422\u043e\u043b\u044c\u043a\u043e iOS","text":"\u041f\u043e\u043b\u0435 \u0414\u0435\u0444\u043e\u043b\u0442 \u0427\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 <code>cameraQuality</code> <code>.high</code> \u043f\u0440\u0435\u0441\u0435\u0442 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0430\u043d\u0430\u043b\u0438\u0437\u0430: <code>.high</code> 1920\u00d71080 / <code>.balanced</code> 1280\u00d7720 / <code>.fast</code> 640\u00d7480 (\u043d\u0430 \u0441\u043b\u0430\u0431\u044b\u0445 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430\u0445 <code>.high</code> \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f) <code>lowResOnWeakDevice</code> <code>false</code> \u043f\u0440\u0438\u043d\u0443\u0434\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 640\u00d7480 \u043d\u0430 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430\u0445 \u0441 \u043c\u0430\u043b\u044b\u043c \u043e\u0431\u044a\u0451\u043c\u043e\u043c \u043f\u0430\u043c\u044f\u0442\u0438 <code>showAnalysisAnimation</code> <code>true</code> \u0441\u043a\u0430\u043d\u0438\u0440\u0443\u044e\u0449\u0430\u044f \u043b\u0438\u043d\u0438\u044f \u0432 \u0444\u0430\u0437\u0435 \u0430\u043d\u0430\u043b\u0438\u0437\u0430 <code>ortIntraOpCap</code> <code>nil</code> \u043f\u043e\u0442\u043e\u043b\u043e\u043a \u043f\u043e\u0442\u043e\u043a\u043e\u0432 \u0438\u043d\u0444\u0435\u0440\u0435\u043d\u0441\u0430; \u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 <code>nil</code>, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0438\u0437\u043c\u0435\u0440\u0438\u043b\u0438 \u043e\u0431\u0440\u0430\u0442\u043d\u043e\u0435 \u2014 SDK \u0432\u044b\u0431\u0438\u0440\u0430\u0435\u0442 \u043f\u043e \u043a\u043b\u0430\u0441\u0441\u0443 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430, \u044f\u0432\u043d\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u043c\u043e\u0436\u0435\u0442 \u043f\u043e\u0434\u043d\u044f\u0442\u044c \u044d\u043d\u0435\u0440\u0433\u043e\u043f\u043e\u0442\u0440\u0435\u0431\u043b\u0435\u043d\u0438\u0435"},{"location":"config.html#android","title":"\u0422\u043e\u043b\u044c\u043a\u043e Android","text":"\u041f\u043e\u043b\u0435 \u0414\u0435\u0444\u043e\u043b\u0442 \u0427\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 <code>scanBothSides</code> <code>false</code> \u0434\u0432\u0443\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0438\u0439 \u0440\u0435\u0436\u0438\u043c \u043e\u0434\u043d\u0438\u043c \u044d\u043a\u0440\u0430\u043d\u043e\u043c: \u043f\u043e\u0441\u043b\u0435 \u043f\u0435\u0440\u0432\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430 \u00ab\u043f\u0435\u0440\u0435\u0432\u0435\u0440\u043d\u0438\u0442\u0435\u00bb, \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u043e\u0431\u0430 \u043a\u0440\u043e\u043f\u0430 <code>targetFps</code> 30 \u0446\u0435\u043b\u0435\u0432\u043e\u0439 FPS \u043a\u0430\u043c\u0435\u0440\u044b (60 \u2014 \u0444\u043b\u0430\u0433\u043c\u0430\u043d\u044b, 15 \u2014 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u044f \u0431\u0430\u0442\u0430\u0440\u0435\u0438) <code>deviceTier</code> <code>null</code> \u044f\u0432\u043d\u044b\u0439 \u043a\u043b\u0430\u0441\u0441 \u0436\u0435\u043b\u0435\u0437\u0430 (0 \u0441\u043b\u0430\u0431\u043e\u0435 / 1 \u0441\u0440\u0435\u0434\u043d\u0435\u0435 / 2 \u043c\u043e\u0449\u043d\u043e\u0435) \u0432\u043c\u0435\u0441\u0442\u043e \u0430\u0432\u0442\u043e\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u2014 \u0432\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 \u0447\u0438\u0441\u043b\u043e \u043f\u043e\u0442\u043e\u043a\u043e\u0432 \u0438\u043d\u0444\u0435\u0440\u0435\u043d\u0441\u0430 <code>analysisResolution</code> <code>AUTO</code> \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043f\u043e\u0442\u043e\u043a\u0430 \u0430\u043d\u0430\u043b\u0438\u0437\u0430: <code>AUTO</code> / <code>FHD_1080P</code> / <code>HD_960P</code> / <code>LOW_480P</code> (\u0432\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e \u043a\u0440\u043e\u043f\u0430 \u0434\u043b\u044f OCR) <code>exposureRoiEnabled</code> <code>true</code> \u044d\u043a\u0441\u043f\u043e\u0437\u0430\u043c\u0435\u0440 \u043f\u043e \u0446\u0435\u043d\u0442\u0440\u0443 \u043a\u0430\u0440\u0442\u044b \u2014 \u0437\u0430\u0449\u0438\u0442\u0430 \u043e\u0442 \u043f\u0435\u0440\u0435\u0441\u0432\u0435\u0442\u0430 \u043d\u0430 \u0443\u043b\u0438\u0446\u0435 <code>staticImageMode</code> <code>false</code> \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u0438 \u0434\u043b\u044f \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0432\u0430\u043d\u0438\u044f \u0441\u0442\u0430\u0442\u0438\u0447\u043d\u044b\u0445 \u0444\u043e\u0442\u043e (\u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0432\u043d\u0443\u0442\u0440\u0438 <code>verify</code>); \u0434\u043b\u044f \u0436\u0438\u0432\u043e\u0439 \u043a\u0430\u043c\u0435\u0440\u044b \u0432\u0441\u0435\u0433\u0434\u0430 <code>false</code> <code>previewOnly</code> <code>false</code> \u043e\u0442\u043b\u0430\u0434\u043e\u0447\u043d\u044b\u0439 \u0440\u0435\u0436\u0438\u043c: \u0442\u0440\u0435\u043a\u0438\u043d\u0433 \u0440\u0430\u043c\u043a\u0438 \u0431\u0435\u0437 \u0437\u0430\u0445\u0432\u0430\u0442\u0430 \u0438 OCR <p>\u0421\u0432\u043e\u044f \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f \u0432 assets (Android)</p> <p>\u0415\u0441\u043b\u0438 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043f\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 <code>config.json</code> \u0432 assets, \u043d\u0435 \u0437\u0430\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0432 \u043d\u0451\u043c \u043a\u043b\u044e\u0447\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u043c\u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 SDK (\u0432 \u0447\u0430\u0441\u0442\u043d\u043e\u0441\u0442\u0438 <code>defer_back_mrz</code>) \u2014 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0439\u0442\u0435 \u043f\u043e\u043b\u044f <code>MergenScannerConfig</code>.</p>"},{"location":"custom-ui.html","title":"\u0421\u0432\u043e\u0439 UI \u043f\u043e\u0432\u0435\u0440\u0445 \u0441\u043a\u0430\u043d\u0435\u0440\u0430","text":"<p>\u0422\u0440\u0438 \u0443\u0440\u043e\u0432\u043d\u044f \u0441\u0432\u043e\u0431\u043e\u0434\u044b \u2014 \u043e\u0442 \u00ab\u043f\u0435\u0440\u0435\u043a\u0440\u0430\u0441\u0438\u0442\u044c \u0440\u0430\u043c\u043a\u0443\u00bb \u0434\u043e \u00ab\u043a\u0430\u043c\u0435\u0440\u0430 \u0438 \u0434\u0432\u0438\u0436\u043e\u043a \u0431\u0435\u0437 \u0435\u0434\u0438\u043d\u043e\u0433\u043e \u043f\u0438\u043a\u0441\u0435\u043b\u044f SDK\u00bb.</p> \u0423\u0440\u043e\u0432\u0435\u043d\u044c \u0427\u0442\u043e \u0434\u0430\u0451\u0442 \u0418\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442 \u0421\u0442\u0438\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0446\u0432\u0435\u0442\u0430, \u0440\u0430\u043c\u043a\u0430, \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0438, \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441 <code>ScannerStyle</code> (\u0441\u043c. \u00ab\u041a\u0430\u0441\u0442\u043e\u043c\u0438\u0437\u0430\u0446\u0438\u044f \u0432\u0438\u0434\u0430\u00bb) \u0421\u0432\u043e\u0439 \u043e\u0432\u0435\u0440\u043b\u0435\u0439 SDK \u0432\u0435\u0434\u0451\u0442 \u043a\u0430\u043c\u0435\u0440\u0443 \u0438 \u0434\u0432\u0438\u0436\u043e\u043a, \u0432\u0435\u0441\u044c UI \u043f\u043e\u0432\u0435\u0440\u0445 \u2014 \u0432\u0430\u0448 <code>onState</code> / <code>customOverlay</code> / \u0440\u0435\u043d\u0434\u0435\u0440\u0435\u0440\u044b Headless SDK \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u0432\u0438\u0436\u043e\u043a \u0438 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435; \u043a\u0430\u043c\u0435\u0440\u0430-\u0432\u044c\u044e \u0438 UI \u0446\u0435\u043b\u0438\u043a\u043e\u043c \u0432\u0430\u0448\u0438 state-handle <p>\u0412\u043e \u0432\u0441\u0435\u0445 \u0432\u0430\u0440\u0438\u0430\u043d\u0442\u0430\u0445 \u043a\u043e\u043e\u0440\u0434\u0438\u043d\u0430\u0442\u043d\u0443\u044e \u0440\u0430\u0431\u043e\u0442\u0443 SDK \u0431\u0435\u0440\u0451\u0442 \u043d\u0430 \u0441\u0435\u0431\u044f: <code>cardBoundsInView</code> \u0438 <code>scanRoiInView</code> \u043f\u0440\u0438\u0445\u043e\u0434\u044f\u0442 \u0443\u0436\u0435 \u0432 \u043a\u043e\u043e\u0440\u0434\u0438\u043d\u0430\u0442\u0430\u0445 \u0432\u044c\u044e (\u043f\u043e\u0432\u043e\u0440\u043e\u0442 \u0438 \u0437\u0430\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u044d\u043a\u0440\u0430\u043d\u0430 \u0443\u0447\u0442\u0435\u043d\u044b) \u2014 \u0440\u0438\u0441\u0443\u0439\u0442\u0435 \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0441\u0447\u0451\u0442\u043e\u0432.</p>"},{"location":"custom-ui.html#2","title":"\u0423\u0440\u043e\u0432\u0435\u043d\u044c 2 \u2014 \u0441\u0432\u043e\u0439 \u043e\u0432\u0435\u0440\u043b\u0435\u0439","text":""},{"location":"custom-ui.html#mergenscanview-onstate","title":"<code>MergenScanView</code> + <code>onState</code>","text":"<p>\u0421\u0430\u043c\u044b\u0439 \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0439 \u043f\u0443\u0442\u044c \u0432 \u043e\u0434\u043d\u043e\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0435\u043c \u0441\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0438: \u043f\u0435\u0440\u0435\u0434\u0430\u0439\u0442\u0435 <code>onState</code>, \u0438 \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0435 \u0442\u0435\u043a\u0441\u0442\u044b SDK \u043f\u043e\u0434\u0430\u0432\u043b\u044f\u044e\u0442\u0441\u044f, \u0430 \u043a\u0430\u0436\u0434\u043e\u0435 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u043a\u0430\u0434\u0440\u0430 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442 \u0432\u0430\u043c (\u043d\u0430 \u0433\u043b\u0430\u0432\u043d\u043e\u043c \u043f\u043e\u0442\u043e\u043a\u0435):</p> iOSAndroid <pre><code>ZStack {\n    MergenScanView(side: .front, license: license,\n                   bboxStyle: .none,\n                   onState: { state = $0 },\n                   onResult: onResult)\n    MyOverlay(state: state)     // \u0440\u0430\u043c\u043a\u0430 \u043f\u043e state.scanRoiInView, \u0442\u0435\u043a\u0441\u0442\u044b, \u043a\u043d\u043e\u043f\u043a\u0438\n}\n</code></pre> <pre><code>Box {\n    MergenScanView(side = MIDSide.FRONT, license = license,\n                   bboxStyle = BBoxDrawStyle.NONE,\n                   onState = { state = it },\n                   onResult = onResult)\n    MyOverlay(state)            // \u0440\u0430\u043c\u043a\u0430 \u043f\u043e state.scanRoiInView, \u0442\u0435\u043a\u0441\u0442\u044b, \u043a\u043d\u043e\u043f\u043a\u0438\n}\n</code></pre> <p>\u0421\u0432\u043e\u0438 \u0442\u0435\u043a\u0441\u0442\u044b \u0441\u0442\u0440\u043e\u0439\u0442\u0435 \u043f\u043e <code>state.scanStatus</code> \u2014 \u043e\u0434\u0438\u043d \u0442\u0438\u043f\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0441\u0442\u0430\u0442\u0443\u0441 \u043d\u0430 \u043a\u0430\u0434\u0440, \u0443\u0436\u0435 \u0441\u0433\u043b\u0430\u0436\u0435\u043d\u043d\u044b\u0439 SDK (\u0441\u043c. \u00ab\u0421\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f \u0438 \u0441\u043e\u0431\u044b\u0442\u0438\u044f\u00bb). \u041e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u0430\u0439\u0442\u0435 <code>Occluded</code> / <code>.occluded</code>: \u043f\u043e\u043a\u0430 \u043e\u043d \u0430\u043a\u0442\u0438\u0432\u0435\u043d, \u0434\u0432\u0438\u0436\u043e\u043a \u043d\u0435 \u0437\u0430\u0445\u0432\u0430\u0442\u044b\u0432\u0430\u0435\u0442 \u043a\u0430\u0434\u0440 (\u043f\u0430\u043b\u0435\u0446 \u043d\u0430 \u0434\u0430\u043d\u043d\u044b\u0445), \u0438 \u0435\u0441\u043b\u0438 \u0432\u0430\u0448 \u043e\u0432\u0435\u0440\u043b\u0435\u0439 \u043e\u0431 \u044d\u0442\u043e\u043c \u043f\u0440\u043e\u043c\u043e\u043b\u0447\u0438\u0442, \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044c \u0443\u0432\u0438\u0434\u0438\u0442 \u043f\u0440\u043e\u0441\u0442\u043e \u0437\u0430\u043c\u0435\u0440\u0448\u0438\u0439 \u0441\u043a\u0430\u043d\u0435\u0440.</p>"},{"location":"custom-ui.html#mergenscannerview","title":"<code>MergenScannerView</code> \u0441 \u043a\u0430\u0441\u0442\u043e\u043c\u043d\u044b\u043c \u043e\u0432\u0435\u0440\u043b\u0435\u0435\u043c","text":"<p>\u041f\u043e\u043b\u043d\u044b\u0439 \u0441\u043a\u0430\u043d\u0435\u0440 (\u0434\u0432\u0443\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0438\u0439 \u0440\u0435\u0436\u0438\u043c, \u044d\u043a\u0440\u0430\u043d \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430, \u0436\u0438\u0437\u043d\u0435\u043d\u043d\u044b\u0439 \u0446\u0438\u043a\u043b) \u0441 \u0432\u0430\u0448\u0438\u043c \u0441\u043b\u043e\u0435\u043c UI:</p> iOS (SwiftUI)iOS (UIKit)Android (Compose)Android (XML) <pre><code>MergenScannerView(licenseKey: license, configuration: config, style: style,\n                  onFinished: { result in ... },\n                  onError:    { error in ... },\n                  onEvent:    { event in ... }) { state in\n    // ViewBuilder-\u043e\u0432\u0435\u0440\u043b\u0435\u0439: \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0439 UI \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u043f\u043e\u0434\u0430\u0432\u043b\u0435\u043d\n    if let bounds = state.cardBoundsInView {\n        MyCardFrame(rect: bounds, color: state.activeColor)\n    }\n}\n</code></pre> <pre><code>let vc = MergenScannerViewController(licenseKey: license, configuration: config)\nvc.onFinished = { result in ... }\nvc.customOverlayRenderer = { ctx, state, width, height in\n    // CGContext-\u0440\u0435\u043d\u0434\u0435\u0440\u0435\u0440; state.cardBoundsInView \u0443\u0436\u0435 \u0432 \u0442\u043e\u0447\u043a\u0430\u0445 \u0432\u044c\u044e\n}\nvc.style = myStyle                  // \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043d\u0435\u043c\u0435\u0434\u043b\u0435\u043d\u043d\u043e\npresent(vc, animated: true)         // fullScreen\n// \u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e: delegate (MergenScannerDelegate), events: AsyncStream&lt;ScannerEvent&gt;,\n// reset() / startScanning() / stopScanning() / release() / setFlashlightEnabled(_:)\n</code></pre> <pre><code>MergenScannerView(\n    licenseJson = license, config = config, style = style,\n    showResultScreen = false,\n    onFinished = { result -&gt; ... },\n    onError    = { e -&gt; ... },\n    onEvent    = { event -&gt; ... },\n    onClose    = { ... },                       // \u0440\u0438\u0441\u0443\u0435\u0442 \u043a\u0440\u0435\u0441\u0442\u0438\u043a, \u0435\u0441\u043b\u0438 \u0437\u0430\u0434\u0430\u043d\n    customOverlay = { state -&gt;                   // BoxScope; \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0439 UI \u043f\u043e\u0434\u0430\u0432\u043b\u0435\u043d\n        state.cardBoundsInView?.let { MyFrame(it, Color(state.activeColorArgb)) }\n    }\n)\n</code></pre> <pre><code>&lt;com.mergen.sdk.MergenScannerView android:id=\"@+id/scanner\" ... /&gt;\n</code></pre> <pre><code>binding.scanner\n    .setConfig(config)\n    .setStyle(style)\n    .setCustomOverlayRenderer { canvas, state, viewWidth, viewHeight -&gt;\n        // Canvas-\u0440\u0435\u043d\u0434\u0435\u0440\u0435\u0440; state.cardBoundsInView \u0443\u0436\u0435 \u0432 \u043f\u0438\u043a\u0441\u0435\u043b\u044f\u0445 \u0432\u044c\u044e\n    }\n    .setOnFinishedListener { result -&gt; ... }\n    .setOnErrorListener { e -&gt; ... }\n    .setOnCloseListener { ... }\n    .setOnGalleryClickListener { ... }\n    .startScanning(license)\n\n// \u0422\u0430\u043a\u0436\u0435: processGalleryImage(bitmap), setFlashlightEnabled(...), reset(),\n// stopScanning() / startScanning(license) \u0434\u043b\u044f \u043f\u0430\u0443\u0437\u044b, release() \u043f\u0440\u0438 \u0443\u0445\u043e\u0434\u0435,\n// events: Flow&lt;ScannerEvent&gt;, showResultScreen = false\n</code></pre> <p>\u0422\u0438\u043f \u0440\u0435\u043d\u0434\u0435\u0440\u0435\u0440\u0430:</p> iOSAndroid <pre><code>public typealias ScannerUIOverlayRenderer =\n    (_ context: CGContext, _ state: ScannerFrameState,\n     _ viewWidth: CGFloat, _ viewHeight: CGFloat) -&gt; Void\n</code></pre> <pre><code>fun interface ScannerOverlayRenderer {\n    fun onDraw(canvas: Canvas, state: ScannerFrameState, viewWidth: Int, viewHeight: Int)\n}\n</code></pre>"},{"location":"custom-ui.html#3-headless","title":"\u0423\u0440\u043e\u0432\u0435\u043d\u044c 3 \u2014 headless","text":"<p>\u0414\u0432\u0438\u0436\u043e\u043a \u0438 \u0436\u0438\u0432\u043e\u0435 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u0431\u0435\u0437 \u043a\u0430\u043a\u043e\u0433\u043e-\u043b\u0438\u0431\u043e \u043a\u0430\u043c\u0435\u0440\u043d\u043e\u0433\u043e UI \u043e\u0442 SDK: \u043f\u0440\u0435\u0432\u044c\u044e, \u043a\u043d\u043e\u043f\u043a\u0438, \u0430\u043d\u0438\u043c\u0430\u0446\u0438\u0438 \u2014 \u0432\u0441\u0451 \u0432\u0430\u0448\u0435.</p> iOSAndroid <pre><code>let handle = MergenScannerStateHandle(licenseKey: license, configuration: config)\n\n// \u041f\u0440\u0435\u0432\u044c\u044e: \u0432\u0441\u0442\u0430\u0432\u044c\u0442\u0435 handle.previewLayer (AVCaptureVideoPreviewLayer) \u0432 \u0441\u0432\u043e\u044e \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u044e\nhandle.updateViewSize(view.bounds.size)     // \u041e\u0411\u042f\u0417\u0410\u0422\u0415\u041b\u042c\u041d\u041e \u0434\u043e \u0441\u0442\u0430\u0440\u0442\u0430 \u0438 \u043f\u0440\u0438 \u0440\u0435\u0441\u0430\u0439\u0437\u0435:\n                                            // \u0431\u0435\u0437 \u043d\u0435\u0433\u043e \u043a\u043e\u043e\u0440\u0434\u0438\u043d\u0430\u0442\u044b \u0432\u044c\u044e \u043d\u0435 \u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f\nhandle.onFinished = { result in ... }\nhandle.startScanning()\n\n// \u0416\u0438\u0432\u043e\u0435 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435: @Published var frameState \u2014 \u043f\u043e\u0434\u043f\u0438\u0441\u043a\u0430 \u0447\u0435\u0440\u0435\u0437 Combine/SwiftUI\n// \u0423\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435: stopScanning() (\u043f\u0430\u0443\u0437\u0430, \u0434\u0432\u0438\u0436\u043e\u043a \u0442\u0451\u043f\u043b\u044b\u0439) / release() (\u043e\u0441\u0432\u043e\u0431\u043e\u0434\u0438\u0442\u044c \u043a\u0430\u043c\u0435\u0440\u0443)\n//             reset() / setFlashlightEnabled(true) / updateStyle(style)\n// \u0413\u0430\u043b\u0435\u0440\u0435\u044f \u0431\u0435\u0437 \u043a\u0430\u043c\u0435\u0440\u044b: handle.processGalleryImage(image) \u2192 onFinished\n// \u0421\u043e\u0431\u044b\u0442\u0438\u044f: handle.events \u2014 AsyncStream&lt;ScannerEvent&gt;; \u043a\u0430\u0436\u0434\u044b\u0439 \u0434\u043e\u0441\u0442\u0443\u043f \u0441\u043e\u0437\u0434\u0430\u0451\u0442\n//          \u041d\u041e\u0412\u042b\u0419 \u0441\u0442\u0440\u0438\u043c \u2014 \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u0435 \u0435\u0433\u043e \u043e\u0434\u0438\u043d \u0440\u0430\u0437\n</code></pre> <pre><code>val handle = rememberMergenScannerState(\n    licenseJson = license, config = config,\n    onFinished = { result -&gt; ... },\n    onError    = { e -&gt; ... },\n)\n\n// \u041f\u0440\u0435\u0432\u044c\u044e: \u0441\u0432\u043e\u0439 CameraX PreviewView\nAndroidView(factory = { ctx -&gt; PreviewView(ctx).also(handle.bindCamera) })\n\n// \u0416\u0438\u0432\u043e\u0435 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435: val state by handle.frameState (Compose State)\n// \u0423\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435: handle.stopScanning() / handle.startScanning() / handle.reset()\n//             handle.release() / handle.setFlashlightEnabled(true)\n// \u0421\u043e\u0431\u044b\u0442\u0438\u044f: handle.events \u2014 Flow&lt;ScannerEvent&gt; (hot: \u0441\u043e\u0431\u0438\u0440\u0430\u0439\u0442\u0435, \u043f\u043e\u043a\u0430 UI \u0432\u0438\u0434\u0435\u043d)\n</code></pre> <p>\u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 headless-\u0441\u043a\u0430\u043d\u0430 \u2014 <code>MergenIdResult</code> (<code>success</code>, <code>croppedImage</code>, <code>croppedImageBack</code> \u0432 \u0434\u0432\u0443\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0435\u043c \u0440\u0435\u0436\u0438\u043c\u0435, <code>confidence</code>, <code>cardVersion</code>, <code>errorCode</code>/<code>errorMessage</code>). \u0414\u043b\u044f \u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0438 \u0432 \u0431\u044b\u0441\u0442\u0440\u0443\u044e \u0441\u0432\u0435\u0440\u043a\u0443 \u0441\u043e\u0431\u0435\u0440\u0438\u0442\u0435 \u0438\u0437 \u043d\u0435\u0433\u043e \u0442\u0438\u043f\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0441\u0442\u043e\u0440\u043e\u043d\u044b:</p> iOSAndroid <pre><code>let scan = MergenSDK.makeScanResult(idResult: idResult, side: .front)\n</code></pre> <pre><code>val scan = Mergen.makeScanResult(idResult, MIDSide.FRONT)\n</code></pre>"},{"location":"custom-ui.html#_1","title":"\u0424\u043e\u043d\u0430\u0440\u0438\u043a","text":"<p>\u0420\u0443\u0447\u043d\u043e\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u2014 <code>setFlashlightEnabled(true/false)</code> \u043d\u0430 headless-\u0445\u044d\u043d\u0434\u043b\u0435, XML-\u0432\u044c\u044e \u0438 UIKit-\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u043b\u0435\u0440\u0435. \u0410\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0440\u0435\u0436\u0438\u043c (<code>autoTorch</code>, \u0432\u043a\u043b\u044e\u0447\u0451\u043d \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e) \u0437\u0430\u0436\u0438\u0433\u0430\u0435\u0442 \u0441\u0432\u0435\u0442 \u043f\u043e\u0441\u043b\u0435 \u0441\u0435\u0440\u0438\u0438 \u0442\u0451\u043c\u043d\u044b\u0445 \u043a\u0430\u0434\u0440\u043e\u0432 \u0438 \u0433\u0430\u0441\u043d\u0435\u0442 \u043f\u0440\u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0438\u0438; \u043b\u044e\u0431\u043e\u0439 \u0440\u0443\u0447\u043d\u043e\u0439 \u0432\u044b\u0437\u043e\u0432 \u0438\u043c\u0435\u0435\u0442 \u043f\u0440\u0438\u043e\u0440\u0438\u0442\u0435\u0442 \u043d\u0430\u0434 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u043a\u043e\u0439.</p>"},{"location":"customization.html","title":"\u041a\u0430\u0441\u0442\u043e\u043c\u0438\u0437\u0430\u0446\u0438\u044f \u0432\u0438\u0434\u0430","text":"<p>\u0412\u043d\u0435\u0448\u043d\u0438\u0439 \u0432\u0438\u0434 \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u043e\u0433\u043e \u043e\u0432\u0435\u0440\u043b\u0435\u044f \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u043e\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 <code>ScannerStyle</code> \u2014 \u0435\u0434\u0438\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 \u043f\u043e\u043b\u0435\u0439 \u043d\u0430 \u043e\u0431\u0435\u0438\u0445 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430\u0445 (Android: \u0440\u0430\u0437\u043c\u0435\u0440\u044b \u0432 dp/sp, \u0446\u0432\u0435\u0442\u0430 ARGB <code>Int</code>; iOS: <code>CGFloat</code> \u0438 <code>Color</code>). \u0421\u0442\u0438\u043b\u044c \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 <code>MergenScannerView</code> (Compose / SwiftUI / XML / UIKit); \u0443 <code>MergenScanView</code> \u0441\u0430\u043c\u044b\u0435 \u0445\u043e\u0434\u043e\u0432\u044b\u0435 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b (<code>bboxColor</code>, <code>bboxStyle</code>, <code>strokeWidth</code>/<code>cornerLength</code>, <code>showGuideFrame</code>, \u043e\u0442\u0441\u0442\u0443\u043f \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441\u0430) \u0432\u044b\u043d\u0435\u0441\u0435\u043d\u044b \u043f\u0440\u044f\u043c\u043e \u0432 \u0441\u0438\u0433\u043d\u0430\u0442\u0443\u0440\u0443.</p> <p>\u0415\u0441\u043b\u0438 \u0441\u0442\u0438\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u043d\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u2014 \u0440\u0438\u0441\u0443\u0439\u0442\u0435 \u043e\u0432\u0435\u0440\u043b\u0435\u0439 \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0441\u0430\u043c\u0438: \u0441\u043c. \u00ab\u0421\u0432\u043e\u0439 UI \u043f\u043e\u0432\u0435\u0440\u0445 \u0441\u043a\u0430\u043d\u0435\u0440\u0430\u00bb.</p>"},{"location":"customization.html#_2","title":"\u0421\u0431\u043e\u0440\u043a\u0430 \u0441\u0442\u0438\u043b\u044f","text":"iOSAndroid <pre><code>let style = ScannerStyle {\n    $0.bboxDrawStyle = .cornersOnly\n    $0.colorSuccess  = Color(red: 0, green: 0.88, blue: 0.46)\n    $0.strokeWidth   = 4\n    $0.hintPositionFraction = 0.15\n}\n// \u041f\u0440\u0435\u0441\u0435\u0442\u044b: ScannerStyle.minimal (\u0442\u043e\u043d\u043a\u0438\u0435 \u0443\u0433\u043e\u043b\u043a\u0438), ScannerStyle.bold (\u0442\u043e\u043b\u0441\u0442\u0430\u044f \u0440\u0430\u043c\u043a\u0430)\n</code></pre> <pre><code>// Kotlin DSL\nval style = ScannerStyle.build {\n    bboxDrawStyle        = BBoxDrawStyle.CORNERS_ONLY\n    colorSuccess         = Color.parseColor(\"#00E676\")\n    strokeWidthDp        = 4f\n    hintPositionFraction = 0.15f\n}\n// \u041f\u0440\u0435\u0441\u0435\u0442\u044b: ScannerStyle.minimal(), ScannerStyle.bold()\n\n// Java-friendly Builder (\u043f\u043e\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u043f\u043e\u043b\u044f; \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u043d\u044b\u0435 \u2014\n// hintCornerRadiusDp, hintPositionFraction, progressTrackColor,\n// progressHeightDp, progressCornerRadiusDp, showAnalyzeAnimation \u2014\n// \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b \u0442\u043e\u043b\u044c\u043a\u043e \u0447\u0435\u0440\u0435\u0437 DSL \u0438\u043b\u0438 copy())\nval style2 = ScannerStyle.Builder()\n    .bboxDrawStyle(BBoxDrawStyle.CORNERS_ONLY)\n    .colorSuccess(Color.GREEN)\n    .build()\n</code></pre>"},{"location":"customization.html#bboxdrawstyle","title":"\u0421\u0442\u0438\u043b\u044c \u0440\u0430\u043c\u043a\u0438 \u2014 <code>BBoxDrawStyle</code>","text":"\u0417\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0412\u0438\u0434 <code>cornersAndRect</code> / <code>CORNERS_AND_RECT</code> \u043f\u043e\u043b\u043d\u044b\u0439 \u043f\u0440\u044f\u043c\u043e\u0443\u0433\u043e\u043b\u044c\u043d\u0438\u043a \u0441 \u0443\u0441\u0438\u043b\u0435\u043d\u043d\u044b\u043c\u0438 \u0443\u0433\u043b\u043e\u0432\u044b\u043c\u0438 \u0430\u043a\u0446\u0435\u043d\u0442\u0430\u043c\u0438 (\u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u0432 <code>ScannerStyle</code>) <code>cornersOnly</code> / <code>CORNERS_ONLY</code> \u0442\u043e\u043b\u044c\u043a\u043e \u0447\u0435\u0442\u044b\u0440\u0435 \u0413-\u043e\u0431\u0440\u0430\u0437\u043d\u044b\u0445 \u0443\u0433\u043b\u043e\u0432\u044b\u0445 \u0441\u043a\u043e\u0431\u043a\u0438 (\u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u0432 <code>MergenScanView</code>) <code>fullRect</code> / <code>FULL_RECT</code> \u043f\u0440\u043e\u0441\u0442\u043e\u0439 \u0441\u043a\u0440\u0443\u0433\u043b\u0451\u043d\u043d\u044b\u0439 \u043f\u0440\u044f\u043c\u043e\u0443\u0433\u043e\u043b\u044c\u043d\u0438\u043a <code>none</code> / <code>NONE</code> \u0440\u0430\u043c\u043a\u0430 \u043d\u0435 \u0440\u0438\u0441\u0443\u0435\u0442\u0441\u044f \u2014 \u0434\u043b\u044f \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0441\u0432\u043e\u0435\u0433\u043e \u043e\u0432\u0435\u0440\u043b\u0435\u044f"},{"location":"customization.html#scannerstyle","title":"\u0412\u0441\u0435 \u043f\u043e\u043b\u044f <code>ScannerStyle</code>","text":"<p>\u0417\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u0435\u0434\u0438\u043d\u044b \u0434\u043b\u044f \u043e\u0431\u0435\u0438\u0445 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c (\u0432 \u0441\u043a\u043e\u0431\u043a\u0430\u0445 \u2014 \u0438\u043c\u044f \u043d\u0430 Android, \u0435\u0441\u043b\u0438 \u043e\u0442\u043b\u0438\u0447\u0430\u0435\u0442\u0441\u044f).</p>"},{"location":"customization.html#_3","title":"\u0420\u0430\u043c\u043a\u0430 \u043a\u0430\u0440\u0442\u044b","text":"\u041f\u043e\u043b\u0435 \u0414\u0435\u0444\u043e\u043b\u0442 \u0427\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 <code>bboxDrawStyle</code> <code>cornersAndRect</code> \u0441\u0442\u0438\u043b\u044c \u0440\u0430\u043c\u043a\u0438 (\u0441\u043c. \u0432\u044b\u0448\u0435) <code>strokeWidth</code> (<code>strokeWidthDp</code>) 3 \u0442\u043e\u043b\u0449\u0438\u043d\u0430 \u043b\u0438\u043d\u0438\u0439 <code>cornerLength</code> (<code>cornerLengthDp</code>) 28 \u0434\u043b\u0438\u043d\u0430 \u043f\u043b\u0435\u0447\u0430 \u0443\u0433\u043b\u043e\u0432\u043e\u0439 \u0441\u043a\u043e\u0431\u043a\u0438 <code>cornerRadius</code> (<code>cornerRadiusDp</code>) 12 \u0441\u043a\u0440\u0443\u0433\u043b\u0435\u043d\u0438\u0435 \u0443\u0433\u043b\u043e\u0432 <code>bboxPaddingFraction</code> 0.04 \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u043e\u0442\u0441\u0442\u0443\u043f \u0432\u043e\u043a\u0440\u0443\u0433 \u0434\u0435\u0442\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u043a\u0430\u0440\u0442\u044b, \u0432 \u0434\u043e\u043b\u044f\u0445 \u043c\u0435\u043d\u044c\u0448\u0435\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b"},{"location":"customization.html#_4","title":"\u0426\u0432\u0435\u0442\u0430 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0439 \u0440\u0430\u043c\u043a\u0438","text":"\u041f\u043e\u043b\u0435 \u0414\u0435\u0444\u043e\u043b\u0442 \u041a\u043e\u0433\u0434\u0430 \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f <code>colorIdle</code> \u0431\u0435\u043b\u044b\u0439 \u043a\u0430\u0440\u0442\u0430 \u043d\u0435 \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0435\u043d\u0430 <code>colorDetecting</code> \u0436\u0451\u043b\u0442\u044b\u0439 \u043a\u0430\u0440\u0442\u0430 \u0432 \u043a\u0430\u0434\u0440\u0435, \u0438\u0434\u0451\u0442 \u0441\u0442\u0430\u0431\u0438\u043b\u0438\u0437\u0430\u0446\u0438\u044f (\u0438\u043c \u0436\u0435 \u043a\u0440\u0430\u0441\u0438\u0442\u0441\u044f \u0430\u043d\u0438\u043c\u0430\u0446\u0438\u044f \u0441\u043a\u0430\u043d\u0438\u0440\u0443\u044e\u0449\u0435\u0439 \u043b\u0438\u043d\u0438\u0438) <code>colorSuccess</code> <code>#00E075</code> \u0443\u0441\u043f\u0435\u0448\u043d\u044b\u0439 \u0437\u0430\u0445\u0432\u0430\u0442 <code>colorFailure</code> \u043a\u0440\u0430\u0441\u043d\u044b\u0439 \u043e\u0448\u0438\u0431\u043a\u0430, \u043e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0435 side-gate, \u043d\u0435\u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435 \u0441\u0442\u043e\u0440\u043e\u043d\u044b"},{"location":"customization.html#_5","title":"\u0417\u0430\u0442\u0435\u043c\u043d\u0435\u043d\u0438\u0435 \u0438 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0438","text":"\u041f\u043e\u043b\u0435 \u0414\u0435\u0444\u043e\u043b\u0442 \u0427\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 <code>dimColor</code> \u0447\u0451\u0440\u043d\u044b\u0439 35% \u043f\u043e\u043b\u043d\u043e\u044d\u043a\u0440\u0430\u043d\u043d\u043e\u0435 \u0437\u0430\u0442\u0435\u043c\u043d\u0435\u043d\u0438\u0435 \u0432\u043e\u043a\u0440\u0443\u0433 \u0440\u0430\u043c\u043a\u0438 <code>hintTextSize</code> (<code>hintTextSizeSp</code>) 15 \u0440\u0430\u0437\u043c\u0435\u0440 \u0442\u0435\u043a\u0441\u0442\u0430 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0438 <code>titleTextSize</code> (<code>titleTextSizeSp</code>) 18 \u0440\u0430\u0437\u043c\u0435\u0440 \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043a\u0430 \u0441\u0442\u0430\u0442\u0443\u0441\u0430 <code>hintTextColor</code> / <code>titleTextColor</code> \u0431\u0435\u043b\u044b\u0439 \u0446\u0432\u0435\u0442\u0430 \u0442\u0435\u043a\u0441\u0442\u0430 <code>hintBackgroundColor</code> \u0447\u0451\u0440\u043d\u044b\u0439 72% \u043f\u043b\u0430\u0448\u043a\u0430 \u043f\u043e\u0434 \u0442\u0435\u043a\u0441\u0442\u043e\u043c <code>hintCornerRadius</code> (<code>hintCornerRadiusDp</code>) 10 \u0441\u043a\u0440\u0443\u0433\u043b\u0435\u043d\u0438\u0435 \u043f\u043b\u0430\u0448\u043a\u0438 <code>hintPositionFraction</code> 0.12 \u043f\u043e\u0437\u0438\u0446\u0438\u044f \u0431\u043b\u043e\u043a\u0430 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0438 \u2014 \u0434\u043e\u043b\u044f \u0432\u044b\u0441\u043e\u0442\u044b \u043e\u0442 \u043d\u0438\u0436\u043d\u0435\u0433\u043e \u043a\u0440\u0430\u044f"},{"location":"customization.html#_6","title":"\u041f\u0440\u043e\u0433\u0440\u0435\u0441\u0441","text":"\u041f\u043e\u043b\u0435 \u0414\u0435\u0444\u043e\u043b\u0442 \u0427\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 <code>showProgressBar</code> <code>false</code> \u043b\u0438\u043d\u0435\u0439\u043d\u044b\u0439 \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441-\u0431\u0430\u0440 (\u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u0435\u0433\u043e \u0440\u043e\u043b\u044c \u0438\u0433\u0440\u0430\u0435\u0442 \u0430\u043d\u0438\u043c\u0430\u0446\u0438\u044f \u0441\u043a\u0430\u043d\u0438\u0440\u0443\u044e\u0449\u0435\u0439 \u043b\u0438\u043d\u0438\u0438) <code>progressColor</code> <code>#00E075</code> \u0437\u0430\u043b\u0438\u0432\u043a\u0430 <code>progressTrackColor</code> \u0431\u0435\u043b\u044b\u0439 25% \u0442\u0440\u0435\u043a <code>progressHeight</code> (<code>progressHeightDp</code>) 4 \u0432\u044b\u0441\u043e\u0442\u0430 <code>progressCornerRadius</code> (<code>progressCornerRadiusDp</code>) 2 \u0441\u043a\u0440\u0443\u0433\u043b\u0435\u043d\u0438\u0435 <code>progressBottomInset</code> (<code>progressBottomOffsetDp</code>) 0 / 92 \u043e\u0442\u0441\u0442\u0443\u043f \u043f\u043e\u043b\u043e\u0441\u044b \u043e\u0442 \u043d\u0438\u0436\u043d\u0435\u0433\u043e \u043a\u0440\u0430\u044f (Android-\u0434\u0435\u0444\u043e\u043b\u0442 92dp \u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u043c\u0435\u0441\u0442\u043e \u043f\u043e\u0434 \u043a\u043d\u043e\u043f\u043a\u0443)"},{"location":"customization.html#_7","title":"\u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e","text":"\u041f\u043e\u043b\u0435 \u0414\u0435\u0444\u043e\u043b\u0442 \u0427\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 <code>showAnalyzeAnimation</code> <code>true</code> \u0430\u043d\u0438\u043c\u0430\u0446\u0438\u044f \u0441\u043a\u0430\u043d\u0438\u0440\u0443\u044e\u0449\u0435\u0439 \u043b\u0438\u043d\u0438\u0438 \u0432\u043d\u0443\u0442\u0440\u0438 \u0440\u0430\u043c\u043a\u0438 \u0432 \u0444\u0430\u0437\u0435 \u0430\u043d\u0430\u043b\u0438\u0437\u0430 <code>showGuideFrame</code> <code>false</code> \u0441\u0442\u0430\u0442\u0438\u0447\u043d\u0430\u044f \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0430\u044f \u0440\u0430\u043c\u043a\u0430 ID-1 \u043f\u043e \u0446\u0435\u043d\u0442\u0440\u0443 + \u0433\u0435\u0439\u0442: \u0437\u0430\u0445\u0432\u0430\u0442 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442\u0441\u044f, \u0442\u043e\u043b\u044c\u043a\u043e \u043a\u043e\u0433\u0434\u0430 \u043a\u0430\u0440\u0442\u0430 \u043f\u0435\u0440\u0435\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u0440\u0430\u043c\u043a\u0443 \u2265 80 % \u043f\u043b\u043e\u0449\u0430\u0434\u0438 <code>showConfidenceLabel</code> <code>false</code> \u043e\u0442\u043b\u0430\u0434\u043e\u0447\u043d\u0430\u044f \u043c\u0435\u0442\u043a\u0430 \u0443\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u0434\u0435\u0442\u0435\u043a\u0446\u0438\u0438 <code>showDebugInfo</code> <code>false</code> \u0437\u0430\u0440\u0435\u0437\u0435\u0440\u0432\u0438\u0440\u043e\u0432\u0430\u043d\u043e <p>\u041d\u0430\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0430\u044f \u0440\u0430\u043c\u043a\u0430</p> <p><code>showGuideFrame = true</code> \u2014 \u0441\u0430\u043c\u044b\u0439 \u043f\u0440\u043e\u0441\u0442\u043e\u0439 \u0441\u043f\u043e\u0441\u043e\u0431 \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u044c \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0439 \u00ab\u043f\u043e\u043b\u043e\u0436\u0438\u0442\u0435 \u043a\u0430\u0440\u0442\u0443 \u0432 \u0440\u0430\u043c\u043a\u0443\u00bb: SDK \u0441\u0430\u043c \u0440\u0438\u0441\u0443\u0435\u0442 \u0440\u0430\u043c\u043a\u0443 \u043f\u0440\u043e\u043f\u043e\u0440\u0446\u0438\u0439 ID-1, \u0437\u0430\u0442\u0435\u043c\u043d\u044f\u0435\u0442 \u043e\u0431\u043b\u0430\u0441\u0442\u044c \u0432\u043d\u0435 \u0435\u0451 \u0438 \u043d\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u0437\u0430\u0445\u0432\u0430\u0442, \u043f\u043e\u043a\u0430 \u043a\u0430\u0440\u0442\u0430 \u043d\u0435 \u0432\u043d\u0443\u0442\u0440\u0438. \u0421\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u00ab\u043a\u0430\u0440\u0442\u0430 \u0432 \u0440\u0430\u043c\u043a\u0435\u00bb \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e \u0438 \u0432\u0430\u0448\u0435\u043c\u0443 \u043a\u043e\u0434\u0443 \u2014 <code>ScannerFrameState.isCardInGuide</code> / <code>cardInGuide</code>.</p>"},{"location":"install.html","title":"\u0423\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u0438 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u044f","text":""},{"location":"install.html#_2","title":"\u0414\u043e\u0441\u0442\u0443\u043f","text":"<p>\u0420\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438 \u043e\u0431\u0435\u0438\u0445 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0435. \u0414\u043b\u044f \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438 \u043d\u0443\u0436\u043d\u044b \u0442\u043e\u043b\u044c\u043a\u043e:</p> <ul> <li>Android: \u043b\u044e\u0431\u043e\u0439 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 GitHub-\u0430\u043a\u043a\u0430\u0443\u043d\u0442 \u0441 classic-\u0442\u043e\u043a\u0435\u043d\u043e\u043c <code>read:packages</code> \u2014   GitHub Packages (Maven) \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0430\u0443\u0442\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044e \u0434\u043b\u044f \u0447\u0442\u0435\u043d\u0438\u044f \u0434\u0430\u0436\u0435 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0445 \u043f\u0430\u043a\u0435\u0442\u043e\u0432;   \u044d\u0442\u043e \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 GitHub, \u0430 \u043d\u0435 \u043f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a\u0430;</li> <li>iOS: \u043d\u0438\u0447\u0435\u0433\u043e \u2014 SPM \u0441\u0442\u0430\u0432\u0438\u0442 \u043f\u0430\u043a\u0435\u0442 \u0431\u0435\u0437 \u0442\u043e\u043a\u0435\u043d\u043e\u0432;</li> <li>\u0444\u0430\u0439\u043b(\u044b) \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438 \u043f\u043e\u0434 \u0432\u0430\u0448\u0438 \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440\u044b \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u2014 \u0443 \u043f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a\u0430.</li> </ul>"},{"location":"install.html#_3","title":"\u041f\u043e\u0434\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435","text":"iOSAndroid <p>Swift Package Manager:</p> <pre><code>.package(url: \"https://github.com/DanielPHP01/MergenSDK-iOS.git\", exact: \"2.6.1\")\n</code></pre> <p>\u041f\u0440\u043e\u0434\u0443\u043a\u0442 \u0434\u043b\u044f \u043b\u0438\u043d\u043a\u043e\u0432\u043a\u0438 \u2014 <code>Mergen</code>.</p> <p>\u0422\u043e\u043b\u044c\u043a\u043e <code>exact:</code></p> <p>\u041d\u0438\u043a\u043e\u0433\u0434\u0430 <code>upToNextMajor</code>. \u0422\u0435\u0433\u0438 \u0434\u0438\u0441\u0442\u0440\u0438\u0431\u0443\u0442\u0438\u0432\u0430 \u043d\u0435 \u043f\u0435\u0440\u0435\u043c\u0435\u0449\u0430\u044e\u0442\u0441\u044f by design \u2014 SPM \u043a\u044d\u0448\u0438\u0440\u0443\u0435\u0442 \u043e\u0442\u043f\u0435\u0447\u0430\u0442\u043a\u0438 \u043f\u0430\u043a\u0435\u0442\u043e\u0432 (<code>~/.swiftpm/security/fingerprints</code>). \u041e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u0432\u0435\u0440\u0441\u0438\u0438 \u2014 \u043e\u0441\u043e\u0437\u043d\u0430\u043d\u043d\u043e\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u043f\u043e changelog \u0440\u0435\u043b\u0438\u0437\u0430.</p> <p>GitHub Packages (Maven). \u0423\u0447\u0451\u0442\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u2014 \u0432 <code>~/.gradle/gradle.properties</code> (<code>gpr.user</code> / <code>gpr.key</code> \u2014 \u0432\u0430\u0448 GitHub-\u043b\u043e\u0433\u0438\u043d \u0438 classic-\u0442\u043e\u043a\u0435\u043d \u0441 \u043f\u0440\u0430\u0432\u043e\u043c <code>read:packages</code>; \u0442\u043e\u043a\u0435\u043d \u043d\u0443\u0436\u0435\u043d \u0434\u0430\u0436\u0435 \u0434\u043b\u044f \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0445 \u043f\u0430\u043a\u0435\u0442\u043e\u0432 \u2014 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 GitHub):</p> <pre><code>// settings.gradle.kts \u2192 dependencyResolutionManagement.repositories\nmaven {\n    url = uri(\"https://maven.pkg.github.com/DanielPHP01/MergenSDK-Android\")\n    credentials {\n        username = providers.gradleProperty(\"gpr.user\").orNull\n        password = providers.gradleProperty(\"gpr.key\").orNull\n    }\n    content { includeGroup(\"com.mergen\") }\n}\n</code></pre> <pre><code>// build.gradle \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f\nimplementation(\"com.mergen:mergen-sdk:2.7.1\")\n</code></pre>"},{"location":"install.html#_4","title":"\u041b\u0438\u0446\u0435\u043d\u0437\u0438\u044f","text":"<p>\u041b\u0438\u0446\u0435\u043d\u0437\u0438\u044f \u2014 JSON-\u0444\u0430\u0439\u043b, \u0432\u044b\u0434\u0430\u0451\u0442\u0441\u044f \u043f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a\u043e\u043c \u043f\u043e\u0434 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u0439 \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f (bundle identifier \u043d\u0430 iOS, applicationId \u043d\u0430 Android) \u0438 \u0438\u043c\u0435\u0435\u0442 \u0441\u0440\u043e\u043a \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f. \u0415\u0441\u043b\u0438 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438 \u0441\u0431\u043e\u0440\u043a\u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442 \u0440\u0430\u0437\u043d\u044b\u0435 \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440\u044b (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0431\u043e\u0435\u0432\u043e\u0439 \u0438 debug \u0441 \u0441\u0443\u0444\u0444\u0438\u043a\u0441\u043e\u043c) \u2014 \u043d\u0430 \u043a\u0430\u0436\u0434\u044b\u0439 \u043d\u0443\u0436\u0435\u043d \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u0444\u0430\u0439\u043b.</p> <p>\u0412\u0441\u0435 \u0432\u044b\u0437\u043e\u0432\u044b SDK \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u044e JSON-\u0441\u0442\u0440\u043e\u043a\u043e\u0439. \u0412 SDK \u0435\u0441\u0442\u044c \u0433\u043e\u0442\u043e\u0432\u044b\u0435 \u0437\u0430\u0433\u0440\u0443\u0437\u0447\u0438\u043a\u0438:</p> iOSAndroid <p>\u0424\u0430\u0439\u043b \u0434\u043e\u0431\u0430\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0432 \u0440\u0435\u0441\u0443\u0440\u0441\u044b \u0442\u0430\u0440\u0433\u0435\u0442\u0430 (Copy Bundle Resources):</p> <pre><code>// \u0447\u0438\u0442\u0430\u0435\u0442 &lt;named&gt;.json \u0438\u0437 \u0431\u0430\u043d\u0434\u043b\u0430; nil \u2014 \u0444\u0430\u0439\u043b\u0430 \u043d\u0435\u0442 \u0438\u043b\u0438 \u043e\u043d \u043f\u0443\u0441\u0442\nlet license = MergenSDK.loadLicense(named: \"license\")   // license.json\n</code></pre> <p>\u0424\u0430\u0439\u043b \u043a\u043b\u0430\u0434\u0451\u0442\u0441\u044f \u0432 <code>assets/</code> (\u0434\u043b\u044f \u0440\u0430\u0437\u043d\u044b\u0445 buildType \u2014 \u0441\u0432\u043e\u0439 \u0444\u0430\u0439\u043b \u0432 \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0435\u043c srcSet, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 <code>src/main/assets/</code> \u0438 <code>src/debug/assets/</code>):</p> <pre><code>// \u0447\u0438\u0442\u0430\u0435\u0442 \u0438\u0437 assets; null \u2014 \u0432\u0430\u043b\u0438\u0434\u043d\u0430\u044f \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u044f \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u0430\nval license = Mergen.loadLicense(context)               // license.json\n// \u0432 Compose \u043e\u0431\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0439\u0442\u0435 \u0432 remember { ... } \u2014 \u0437\u0430\u0433\u0440\u0443\u0437\u0447\u0438\u043a \u043d\u0435 \u043a\u044d\u0448\u0438\u0440\u0443\u0435\u0442\n</code></pre> <p>\u041e\u0448\u0438\u0431\u043a\u0430 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438</p> <p>\u0422\u0435\u0441\u0442\u043e\u0432\u044b\u0435 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438 \u043a\u043e\u0440\u043e\u0442\u043a\u043e\u0436\u0438\u0432\u0443\u0449\u0438\u0435: \u043f\u0440\u0438 \u043e\u0448\u0438\u0431\u043a\u0435 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438 \u043f\u0435\u0440\u0432\u044b\u043c \u0434\u0435\u043b\u043e\u043c \u043f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0441\u0440\u043e\u043a \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f. \u0411\u043e\u0435\u0432\u044b\u0435 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438 \u0432\u044b\u043f\u0443\u0441\u043a\u0430\u044e\u0442\u0441\u044f \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u043f\u0435\u0440\u0435\u0434 \u0440\u0435\u043b\u0438\u0437\u043e\u043c.</p>"},{"location":"scan.html","title":"\u0421\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0441\u0442\u043e\u0440\u043e\u043d\u044b","text":"<p>\u0421\u043a\u0430\u043d \u043e\u0434\u043d\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u043a\u0430\u0440\u0442\u044b \u0436\u0438\u0432\u043e\u0439 \u043a\u0430\u043c\u0435\u0440\u043e\u0439 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442 \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442 <code>MergenScanView</code>. \u041e\u043d \u0441\u0430\u043c \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u043a\u0430\u043c\u0435\u0440\u043e\u0439 \u0438 \u0434\u0432\u0438\u0436\u043a\u043e\u043c, \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0441\u0442\u0430\u0442\u0443\u0441\u044b \u0438 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0440\u043e\u0432\u043d\u043e \u043e\u0434\u0438\u043d \u0440\u0430\u0437 \u0447\u0435\u0440\u0435\u0437 <code>onResult</code>.</p>"},{"location":"scan.html#_2","title":"\u041f\u0440\u043e\u0433\u0440\u0435\u0432","text":"<p>\u041c\u043e\u0434\u0435\u043b\u0438 \u0437\u0430\u0433\u0440\u0443\u0436\u0430\u044e\u0442\u0441\u044f \u043e\u0434\u0438\u043d \u0440\u0430\u0437 \u043d\u0430 \u043f\u0440\u043e\u0446\u0435\u0441\u0441. \u0414\u0432\u0430 \u0443\u0440\u043e\u0432\u043d\u044f:</p> iOSAndroid <pre><code>// \u0411\u0430\u0437\u043e\u0432\u044b\u0439 \u043f\u0440\u043e\u0433\u0440\u0435\u0432 (\u0434\u0432\u0438\u0436\u043e\u043a, \u0431\u0435\u0437 \u043a\u0430\u043c\u0435\u0440\u044b)\nMergenSDK.warmUp(license: license)\n\n// \u041f\u0440\u043e\u0433\u0440\u0435\u0432 + \u0443\u043f\u0440\u0435\u0436\u0434\u0430\u044e\u0449\u0430\u044f \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0430 MRZ-\u043c\u043e\u0434\u0435\u043b\u0435\u0439 (\u0434\u043b\u044f \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0435\u0432 \u0441 verify)\nMergenSDK.preload(licenseKey: license)\n</code></pre> <pre><code>// \u0411\u0430\u0437\u043e\u0432\u044b\u0439 \u043f\u0440\u043e\u0433\u0440\u0435\u0432 (\u0434\u0432\u0438\u0436\u043e\u043a, \u0431\u0435\u0437 \u043a\u0430\u043c\u0435\u0440\u044b) \u2014 fire-and-forget\nMergen.warmUp(context, license)\n\n// \u041f\u0440\u043e\u0433\u0440\u0435\u0432 + \u0443\u043f\u0440\u0435\u0436\u0434\u0430\u044e\u0449\u0430\u044f \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0430 MRZ-\u043c\u043e\u0434\u0435\u043b\u0435\u0439 (\u0434\u043b\u044f \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0435\u0432 \u0441 verify)\nMergen.preload(context, license)\n</code></pre> <p>\u041e\u0431\u0430 \u0432\u044b\u0437\u043e\u0432\u0430 \u0438\u0434\u0435\u043c\u043f\u043e\u0442\u0435\u043d\u0442\u043d\u044b. \u041f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b <code>leanFields</code> / <code>useUnifiedDetector</code> (\u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e <code>true</code>) \u0434\u043e\u043b\u0436\u043d\u044b \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u0442\u044c \u0441 \u0442\u0435\u043c\u0438, \u0447\u0442\u043e \u0431\u0443\u0434\u0443\u0442 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c\u0441\u044f \u043f\u0440\u0438 \u0441\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0438 \u0438 \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438 \u2014 \u0438\u043d\u0430\u0447\u0435 \u043f\u0440\u043e\u0433\u0440\u0435\u0442\u044b\u0439 \u0434\u0432\u0438\u0436\u043e\u043a \u043d\u0435 \u043f\u0435\u0440\u0435\u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f. \u041d\u0430 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430\u0445 \u0441 \u041e\u0417\u0423 \u043c\u0435\u043d\u044c\u0448\u0435 5 \u0413\u0411 \u0443\u043f\u0440\u0435\u0436\u0434\u0430\u044e\u0449\u0430\u044f \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0430 MRZ-\u043c\u043e\u0434\u0435\u043b\u0435\u0439 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043f\u0440\u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442\u0441\u044f (\u0437\u0430\u0449\u0438\u0442\u0430 \u043e\u0442 \u043d\u0435\u0445\u0432\u0430\u0442\u043a\u0438 \u043f\u0430\u043c\u044f\u0442\u0438) \u2014 \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u0432 \u044d\u0442\u043e\u043c \u0441\u043b\u0443\u0447\u0430\u0435 \u0434\u043e\u0433\u0440\u0443\u0437\u0438\u0442 \u0438\u0445 \u043f\u043e \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044e.</p>"},{"location":"scan.html#android","title":"\u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430 (Android)","text":"<p>SDK \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 64-\u0431\u0438\u0442\u043d\u044b\u0445 ARM-\u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430\u0445. \u041f\u0440\u043e\u0432\u0435\u0440\u044f\u0439\u0442\u0435 \u0434\u043e \u043e\u0442\u043a\u0440\u044b\u0442\u0438\u044f \u0441\u043a\u0430\u043d\u0435\u0440\u0430:</p> <pre><code>if (!Mergen.isDeviceSupported()) {\n    val reason = Mergen.unsupportedDeviceReason()   // UnsupportedAbiException? \u0441 userMessage\n    // \u043f\u043e\u043a\u0430\u0436\u0438\u0442\u0435 reason?.userMessage \u0438 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0438\u0442\u0435 \u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u043f\u0443\u0442\u044c\n}\n</code></pre> <p>\u041d\u0430 iOS \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0430\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043d\u0435 \u043d\u0443\u0436\u043d\u0430 \u2014 \u0432\u0441\u0435 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u043c\u044b\u0435 iPhone (8 / X \u0438 \u043d\u043e\u0432\u0435\u0435) 64-\u0431\u0438\u0442\u043d\u044b\u0435.</p>"},{"location":"scan.html#mergenscanview","title":"<code>MergenScanView</code>","text":"iOSAndroid <p>SwiftUI; \u0432 UIKit \u043e\u0431\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0432 <code>UIHostingController</code>.</p> <pre><code>MergenScanView(\n    side:                MIDSide,                          // .front / .back\n    license:             String?              = nil,       // nil \u2192 license.json \u0438\u0437 \u0431\u0430\u043d\u0434\u043b\u0430\n    configuration:       MergenScannerConfig  = .init(),   // \u0441\u043c. \u00ab\u041a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f\u00bb\n    bboxColor:           String?              = nil,       // hex \"RRGGBB\"/\"RRGGBBAA\"\n    bboxStyle:           BBoxDrawStyle        = .cornersOnly,\n    strokeWidth:         CGFloat              = 3,\n    cornerLength:        CGFloat              = 28,\n    showGuideFrame:      Bool                 = false,\n    progressBottomInset: CGFloat              = 0,\n    scanRoi:             CGRect?              = nil,       // \u043f\u0435\u0440\u0435\u043a\u0440\u044b\u0432\u0430\u0435\u0442 configuration.scanRoi\n    onState:             ((ScannerFrameState) -&gt; Void)? = nil,  // \u0441\u0432\u043e\u0439 \u043e\u0432\u0435\u0440\u043b\u0435\u0439\n    onResult:            @escaping (MergenScanResult) -&gt; Void\n)\n</code></pre> <p>Jetpack Compose.</p> <pre><code>MergenScanView(\n    side                   : MIDSide,                     // FRONT / BACK\n    license                : String? = null,              // null \u2192 license.json \u0438\u0437 assets\n    bboxColor              : String? = null,              // hex \"RRGGBB\"/\"AARRGGBB\"\n    bboxStyle              : BBoxDrawStyle = BBoxDrawStyle.CORNERS_ONLY,\n    cornerLengthDp         : Float? = null,\n    scanSpeed              : ScanSpeed? = null,           // FAST / NORMAL / THOROUGH\n    sideGate               : SideGateConfig = SideGateConfig(),\n    progressBottomOffsetDp : Float? = null,\n    analyzeAnimEnabled     : Boolean = true,\n    captureHintsEnabled    : Boolean = true,\n    useUnifiedDetector     : Boolean = true,\n    liveVersionProbeConf   : Float = 0.65f,\n    showGuideFrame         : Boolean = false,\n    deviceTier             : Int? = null,\n    scanRoi                : RectF? = null,\n    deferBackMrz           : Boolean = false,\n    onError                : ((Throwable) -&gt; Unit)? = null,\n    onState                : ((ScannerFrameState) -&gt; Unit)? = null,  // \u0441\u0432\u043e\u0439 \u043e\u0432\u0435\u0440\u043b\u0435\u0439\n    onResult               : (MergenScanResult) -&gt; Unit,\n)\n</code></pre> <p><code>side</code> \u2014 \u0434\u0435\u043a\u043b\u0430\u0440\u0430\u0442\u0438\u0432\u043d\u0430\u044f \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430 \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b: \u043e\u043d\u0430 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f \u0432 <code>MergenScanResult.side</code> \u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u0432\u0430\u0448\u0438\u043c\u0438 UX-\u0442\u0435\u043a\u0441\u0442\u0430\u043c\u0438; \u0434\u0432\u0438\u0436\u043e\u043a \u043f\u0440\u0438 \u044d\u0442\u043e\u043c \u043a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u0442 \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u0441\u0442\u043e\u0440\u043e\u043d\u0443 \u0441\u0430\u043c (<code>detectedSide</code>). \u0416\u0451\u0441\u0442\u043a\u043e\u0435 \u043e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0435 \u00ab\u043d\u0435 \u0442\u043e\u0439\u00bb \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f side-gate'\u043e\u043c (\u0441\u043c. \u00ab\u041a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f\u00bb).</p> <p>\u041a\u043e\u0433\u0434\u0430 \u0437\u0430\u0434\u0430\u043d <code>onState</code>, \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0435 \u0442\u0435\u043a\u0441\u0442\u044b SDK \u043f\u043e\u0434\u0430\u0432\u043b\u044f\u044e\u0442\u0441\u044f, \u0438 \u043a\u0430\u0436\u0434\u043e\u0435 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u043a\u0430\u0434\u0440\u0430 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442 \u0432 \u0432\u0430\u0448\u0443 \u043b\u044f\u043c\u0431\u0434\u0443 \u2014 \u0441\u043c. \u00ab\u0421\u0432\u043e\u0439 UI \u043f\u043e\u0432\u0435\u0440\u0445 \u0441\u043a\u0430\u043d\u0435\u0440\u0430\u00bb.</p> <p><code>scanRoi</code> \u2014 \u043e\u0441\u0438 \u0440\u0430\u0437\u043b\u0438\u0447\u0430\u044e\u0442\u0441\u044f \u043c\u0435\u0436\u0434\u0443 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430\u043c\u0438</p> <p>\u0417\u043e\u043d\u0430 \u0441\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u0437\u0430\u0434\u0430\u0451\u0442\u0441\u044f \u0432 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u043a\u043e\u043e\u0440\u0434\u0438\u043d\u0430\u0442\u0430\u0445 0\u20261. \u041a\u0430\u0434\u0440 \u043e\u0431\u0440\u0435\u0437\u0430\u0435\u0442\u0441\u044f \u0434\u043e \u0434\u0435\u0442\u0435\u043a\u0446\u0438\u0438: \u043a\u0430\u0440\u0442\u0430 \u0432\u043d\u0435 \u0437\u043e\u043d\u044b \u043d\u0435 \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u0432\u043e\u0432\u0441\u0435, \u043e\u0431\u043b\u0430\u0441\u0442\u044c \u0432\u043d\u0435 \u0437\u043e\u043d\u044b \u0437\u0430\u0442\u0435\u043c\u043d\u044f\u0435\u0442\u0441\u044f, \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u0432 \u043a\u043e\u043e\u0440\u0434\u0438\u043d\u0430\u0442\u0430\u0445 \u043f\u043e\u043b\u043d\u043e\u0433\u043e \u043a\u0430\u0434\u0440\u0430. \u041c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0440\u0430\u0437\u043c\u0435\u0440 \u0437\u043e\u043d\u044b \u2014 0.15 \u043f\u043e \u043a\u0430\u0436\u0434\u043e\u0439 \u043e\u0441\u0438. \u041d\u0430 iOS \u043e\u0441\u0438 \u044d\u043a\u0440\u0430\u043d\u043d\u044b\u0435 (<code>x</code> \u2014 \u0433\u043e\u0440\u0438\u0437\u043e\u043d\u0442\u0430\u043b\u044c), \u043d\u0430 Android \u2014 \u043e\u0441\u0438 \u0431\u0443\u0444\u0435\u0440\u0430 \u0430\u043d\u0430\u043b\u0438\u0437\u0430 (\u043e\u0431\u0440\u0430\u0442\u043d\u044b\u0435). \u041e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435 \u0447\u0438\u0441\u043b\u0430 \u0434\u0430\u044e\u0442 \u0440\u0430\u0437\u043d\u044b\u0435 \u043e\u043a\u043d\u0430. \u042d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u0430\u044f \u043f\u0430\u0440\u0430 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0439: iOS <code>CGRect(x: 0.05, y: 0.28, width: 0.90, height: 0.44)</code> \u2261 Android <code>RectF(0.28f, 0.05f, 0.72f, 0.95f)</code>.</p>"},{"location":"scan.html#frame-gate","title":"\u041a\u0430\u0434\u0440-\u0433\u0435\u0439\u0442: \u043f\u0430\u043b\u0435\u0446 \u043d\u0430 \u0434\u0430\u043d\u043d\u044b\u0445 \u0438 \u0430\u0432\u0442\u043e-\u0440\u0430\u0437\u0432\u043e\u0440\u043e\u0442","text":"<p>\u0412\u043e \u0432\u0440\u0435\u043c\u044f \u043d\u0430\u0432\u0435\u0434\u0435\u043d\u0438\u044f SDK \u0440\u0430\u0437 \u0432 350 \u043c\u0441 \u043f\u0440\u043e\u0433\u043e\u043d\u044f\u0435\u0442 \u043f\u043e \u0432\u044b\u043f\u0440\u044f\u043c\u043b\u0435\u043d\u043d\u043e\u043c\u0443 \u043a\u0440\u043e\u043f\u0443 \u043a\u0430\u0440\u0442\u044b \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0443\u044e \u043c\u043e\u0434\u0435\u043b\u044c \u043a\u0430\u0434\u0440-\u0433\u0435\u0439\u0442\u0430. \u041e\u0431\u0435 \u0435\u0451 \u0444\u0443\u043d\u043a\u0446\u0438\u0438 \u0432\u043a\u043b\u044e\u0447\u0435\u043d\u044b \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u0438 \u0432\u0438\u0434\u043d\u044b \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044e.</p> <p>\u041f\u0435\u0440\u0435\u0432\u0451\u0440\u043d\u0443\u0442\u0430\u044f \u043a\u0430\u0440\u0442\u0430 \u0440\u0430\u0437\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0441\u0430\u043c\u0430. \u041e\u0440\u0438\u0435\u043d\u0442\u0430\u0446\u0438\u044f \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f \u0434\u043e \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0432\u0430\u043d\u0438\u044f (\u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c 0.9963 \u043d\u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0445 \u043a\u0440\u043e\u043f\u0430\u0445), \u0438 \u0432 OCR \u043a\u0440\u043e\u043f \u0443\u0445\u043e\u0434\u0438\u0442 \u0443\u0436\u0435 \u00ab\u0433\u043e\u043b\u043e\u0432\u043e\u0439 \u0432\u0432\u0435\u0440\u0445\u00bb. \u0420\u0430\u043d\u044c\u0448\u0435 \u043f\u0435\u0440\u0435\u0432\u0451\u0440\u043d\u0443\u0442\u044b\u0439 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u0441\u0442\u043e\u0438\u043b \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430 \u0432\u0441\u0435\u0433\u043e \u043a\u0430\u0441\u043a\u0430\u0434\u0430 \u2014 \u043d\u0430 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435 \u044d\u0442\u043e \u0441\u0435\u043a\u0443\u043d\u0434\u044b \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u044f, \u2014 \u0438 \u043c\u043e\u0433 \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u044c \u043d\u0435\u0432\u0435\u0440\u043d\u043e \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u0443\u044e \u0441\u0442\u043e\u0440\u043e\u043d\u0443.</p> <p>\u041f\u0430\u043b\u0435\u0446 \u043d\u0430 \u0434\u0430\u043d\u043d\u044b\u0445 \u0431\u043b\u043e\u043a\u0438\u0440\u0443\u0435\u0442 \u0437\u0430\u0445\u0432\u0430\u0442. \u041f\u043e\u043a\u0430 \u043f\u043e\u043c\u0435\u0445\u0430 \u0432\u0438\u0434\u043d\u0430:</p> <ul> <li>\u0440\u0430\u043c\u043a\u0430 \u043a\u0430\u0440\u0442\u044b \u0433\u043e\u0440\u0438\u0442 \u0446\u0432\u0435\u0442\u043e\u043c <code>colorFailure</code> (\u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u043a\u0440\u0430\u0441\u043d\u044b\u043c) \u2014 \u0442\u0430\u043a \u0436\u0435, \u043a\u0430\u043a \u043f\u0440\u0438   \u043e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0438 \u043f\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u0435 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430;</li> <li><code>messageTitle</code> \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0437\u0430\u043a\u0440\u044b\u0442\u043e\u0435 \u043f\u043e\u043b\u0435: \u00ab\u0423\u0431\u0435\u0440\u0438\u0442\u0435 \u043f\u0430\u043b\u0435\u0446 \u0441 \u043d\u043e\u043c\u0435\u0440\u0430 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u00bb,   \u00ab\u0423\u0431\u0435\u0440\u0438\u0442\u0435 \u043f\u0430\u043b\u0435\u0446 \u0441 MRZ\u00bb, \u00ab\u0423\u0431\u0435\u0440\u0438\u0442\u0435 \u043f\u0430\u043b\u0435\u0446 \u0441 \u0444\u043e\u0442\u043e\u00bb. \u041a\u043e\u0433\u0434\u0430 \u043f\u043e\u043b\u0435 \u043d\u0430\u0437\u0432\u0430\u0442\u044c \u043d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u2014   \u00ab\u0423\u0431\u0435\u0440\u0438\u0442\u0435 \u043f\u0430\u043b\u0435\u0446 \u0441 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u00bb;</li> <li>\u0441\u043a\u0430\u043d \u043d\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442\u0441\u044f \u0441\u0430\u043c \u0441\u043e\u0431\u043e\u0439: \u0437\u0430\u0445\u0432\u0430\u0442 \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442\u0441\u044f, \u043f\u043e\u043a\u0430 \u043f\u0430\u043b\u0435\u0446 \u043d\u0435 \u0443\u0431\u0435\u0440\u0443\u0442.</li> </ul> <p>\u041f\u043e\u0440\u043e\u0433 \u0432\u044b\u0441\u0442\u0430\u0432\u043b\u0435\u043d \u043a\u043e\u043d\u0441\u0435\u0440\u0432\u0430\u0442\u0438\u0432\u043d\u043e: \u043d\u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0445 \u043a\u0430\u0434\u0440\u0430\u0445 \u043f\u043e\u043c\u0435\u0445\u0430 \u043b\u043e\u0432\u0438\u0442\u0441\u044f \u0432 11 \u0441\u043b\u0443\u0447\u0430\u044f\u0445 \u0438\u0437 12, \u0430 \u043b\u043e\u0436\u043d\u044b\u0445 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0439 \u043d\u0435\u0442 \u043d\u0438 \u043d\u0430 68 \u0447\u0438\u0441\u0442\u044b\u0445 \u043a\u0440\u043e\u043f\u0430\u0445, \u043d\u0438 \u043d\u0430 12 \u043a\u0430\u0434\u0440\u0430\u0445 \u00ab\u043a\u0430\u0440\u0442\u0443 \u0434\u0435\u0440\u0436\u0430\u0442 \u0437\u0430 \u043a\u0440\u043e\u043c\u043a\u0443\u00bb, \u043d\u0438 \u043d\u0430 38 \u043b\u0438\u0446\u0435\u0432\u044b\u0445 \u0441\u0442\u043e\u0440\u043e\u043d\u0430\u0445 \u0441 \u043f\u043e\u0440\u0442\u0440\u0435\u0442\u043e\u043c \u2014 \u043f\u043e\u0440\u0442\u0440\u0435\u0442 \u0432\u043b\u0430\u0434\u0435\u043b\u044c\u0446\u0430 \u0437\u0430 \u043f\u0430\u043b\u0435\u0446 \u043d\u0435 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442\u0441\u044f. \u0417\u0430\u043a\u0440\u044b\u0442\u043e\u0435 \u043f\u043e\u043b\u0435 \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432\u0435\u0440\u043d\u043e \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0432 8 \u0441\u043b\u0443\u0447\u0430\u044f\u0445 \u0438\u0437 10.</p> <p>\u041f\u0440\u0435\u0434\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u0435\u043b\u044c: \u0435\u0441\u043b\u0438 \u043f\u043e\u043c\u0435\u0445\u0430 \u00ab\u0432\u0438\u0434\u043d\u0430\u00bb \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u043e \u0434\u043e\u043b\u044c\u0448\u0435 20 \u0441, \u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u043a\u0430 \u0441\u043d\u0438\u043c\u0430\u0435\u0442\u0441\u044f. \u041b\u043e\u0436\u043d\u043e\u0435 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0435 \u043d\u0435 \u0434\u043e\u043b\u0436\u043d\u043e \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0442\u044c\u0441\u044f \u0432 \u00ab\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u043e\u0442\u0441\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u0442\u044c\u00bb.</p> <p>\u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0442\u0435\u043d\u0438 \u0438 \u0433\u0440\u044f\u0437\u0438 \u0432 \u043c\u043e\u0434\u0435\u043b\u0438 \u0435\u0441\u0442\u044c, \u043d\u043e \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d\u044b \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u2014 \u043f\u043e\u0447\u0435\u043c\u0443 \u0438\u043c\u0435\u043d\u043d\u043e, \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u043e \u0432 \u00ab\u041a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438\u00bb \u0432\u043c\u0435\u0441\u0442\u0435 \u0441\u043e \u0432\u0441\u0435\u043c\u0438 \u043a\u043b\u044e\u0447\u0430\u043c\u0438 \u0433\u0435\u0439\u0442\u0430.</p> <p>\u0421\u0432\u043e\u0435\u043c\u0443 UI \u043f\u043e\u043c\u0435\u0445\u0430 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0430 \u0442\u0440\u0435\u043c\u044f \u0441\u043f\u043e\u0441\u043e\u0431\u0430\u043c\u0438 \u0441\u0440\u0430\u0437\u0443 \u2014 \u043e\u043d\u0438 \u043d\u0435 \u043c\u043e\u0433\u0443\u0442 \u0440\u0430\u0437\u043e\u0439\u0442\u0438\u0441\u044c: \u0441\u0442\u0430\u0442\u0443\u0441 <code>ScanStatus.Occluded</code> / <code>.occluded</code>, \u043f\u043e\u043b\u044f \u043a\u0430\u0434\u0440\u0430 <code>isFingerOccluded</code> / <code>isShadowed</code> / <code>occlusionType</code> / <code>occludedFieldId</code> \u0438 \u0433\u043e\u0442\u043e\u0432\u0430\u044f \u0441\u0442\u0440\u043e\u043a\u0430 <code>messageTitle</code>.</p> <p>\u041b\u043e\u043c\u0430\u044e\u0449\u0435\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 2.6.0</p> <p>\u0421\u0442\u0430\u0442\u0443\u0441 <code>Occluded</code> / <code>.occluded</code> \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d \u0432 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044e\u0449\u0435\u0435 \u043f\u0435\u0440\u0435\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0435 <code>ScanStatus</code>: \u0438\u0441\u0447\u0435\u0440\u043f\u044b\u0432\u0430\u044e\u0449\u0438\u0435 <code>when</code> (Kotlin) \u0438 <code>switch</code> (Swift) \u0431\u0435\u0437 \u043d\u043e\u0432\u043e\u0439 \u0432\u0435\u0442\u043a\u0438 \u043d\u0435 \u0441\u043e\u0431\u0435\u0440\u0443\u0442\u0441\u044f. \u041f\u0440\u0438\u043c\u0435\u0440\u044b \u043c\u0438\u0433\u0440\u0430\u0446\u0438\u0438 \u2014 \u0432 \u0440\u0430\u0437\u0434\u0435\u043b\u0435 \u00ab\u0421\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f \u0438 \u0441\u043e\u0431\u044b\u0442\u0438\u044f\u00bb.</p>"},{"location":"scan.html#mergenscanresult","title":"<code>MergenScanResult</code> \u2014 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0441\u043a\u0430\u043d\u0430 \u0441\u0442\u043e\u0440\u043e\u043d\u044b","text":"\u041f\u043e\u043b\u0435 \u0422\u0438\u043f \u0427\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442 <code>side</code> <code>MIDSide</code> \u0441\u0442\u043e\u0440\u043e\u043d\u0430, \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u043d\u0430\u044f \u043f\u0440\u0438 \u0437\u0430\u043f\u0443\u0441\u043a\u0435 <code>detectedSide</code> <code>MIDSide?</code> \u0441\u0442\u043e\u0440\u043e\u043d\u0430, \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u043d\u043d\u0430\u044f \u0434\u0432\u0438\u0436\u043a\u043e\u043c; <code>nil</code>/<code>null</code> \u2014 \u043a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440 \u043d\u0435 \u0441\u0440\u0430\u0431\u043e\u0442\u0430\u043b <code>generation</code> <code>MergenDocGeneration?</code> \u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u0435 \u043c\u0430\u043a\u0435\u0442\u0430: <code>y2008</code> / <code>y2017</code> / <code>y2025</code> <code>version</code> <code>String</code> \u0441\u0442\u0440\u043e\u043a\u0430 \u0432\u0435\u0440\u0441\u0438\u0438 \u0446\u0435\u043b\u0438\u043a\u043e\u043c, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 <code>\"Front2017\"</code> <code>docNumber</code> <code>String?</code> \u043d\u043e\u043c\u0435\u0440 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430, \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043d\u043d\u044b\u0439 \u0441 \u044d\u0442\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b <code>pin</code> <code>String?</code> \u041f\u0418\u041d (\u0443 \u043b\u0438\u0446\u0435\u0432\u044b\u0445 2017/2025 \u043d\u0430 \u043a\u0430\u0440\u0442\u0435 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442) <code>mrz</code> <code>String?</code> \u0441\u0442\u0440\u043e\u043a\u0438 MRZ \u0447\u0435\u0440\u0435\u0437 <code>\\n</code> (\u0442\u043e\u043b\u044c\u043a\u043e \u043e\u0431\u043e\u0440\u043e\u0442\u044b; \u043f\u0440\u0438 <code>deferBackMrz</code> \u0437\u0430\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u043d\u0430 \u044d\u0442\u0430\u043f\u0435 <code>verify</code>) <code>croppedPhoto</code> <code>UIImage?</code> / <code>Bitmap?</code> \u043a\u0440\u043e\u043f \u043a\u0430\u0440\u0442\u044b \u0441 \u043a\u043e\u0440\u0440\u0435\u043a\u0446\u0438\u0435\u0439 \u043f\u0435\u0440\u0441\u043f\u0435\u043a\u0442\u0438\u0432\u044b; <code>nil</code> \u043f\u0440\u0438 \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e\u043c \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435 <code>hasSideSnapshot</code> <code>Bool</code> \u043f\u0440\u0438\u0433\u043e\u0434\u0435\u043d \u043b\u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0434\u043b\u044f \u0431\u044b\u0441\u0442\u0440\u043e\u0433\u043e \u043f\u0443\u0442\u0438 <code>verifyCards</code> (~1 \u043c\u0441) <p>\u0413\u043e\u0442\u043e\u0432\u044b\u0435 \u043f\u0440\u0438\u0437\u043d\u0430\u043a\u0438 \u0434\u043b\u044f UX:</p> <ul> <li><code>side != detectedSide</code> \u2014 \u00ab\u043f\u043e\u043a\u0430\u0437\u0430\u043d\u0430 \u043d\u0435 \u0442\u0430 \u0441\u0442\u043e\u0440\u043e\u043d\u0430\u00bb;</li> <li>\u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 <code>generation</code> \u043c\u0435\u0436\u0434\u0443 \u0441\u0442\u043e\u0440\u043e\u043d\u0430\u043c\u0438 \u2014 \u0432\u0435\u0440\u043e\u044f\u0442\u043d\u043e, \u0434\u0432\u0435 \u0440\u0430\u0437\u043d\u044b\u0435 \u043a\u0430\u0440\u0442\u044b.</li> </ul> <pre><code>public enum MergenDocGeneration: String { case y2008 = \"2008\"; case y2017 = \"2017\"; case y2025 = \"2025\" }\n</code></pre> <ul> <li><code>y2008</code> \u2014 \u041f\u0418\u041d \u043d\u0430\u043f\u0435\u0447\u0430\u0442\u0430\u043d \u043d\u0430 \u043b\u0438\u0446\u0435\u0432\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u0435;</li> <li><code>y2017</code> \u2014 \u041f\u0418\u041d \u0442\u043e\u043b\u044c\u043a\u043e \u0432 MRZ \u043d\u0430 \u043e\u0431\u043e\u0440\u043e\u0442\u0435;</li> <li><code>y2025</code> \u2014 \u043e\u0431\u043d\u043e\u0432\u043b\u0451\u043d\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d, \u0444\u043e\u0440\u043c\u0430\u0442 MRZ \u043a\u0430\u043a \u0443 2017.</li> </ul> <p>\u0414\u043b\u044f \u0441\u0435\u0440\u0438\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0439\u0442\u0435 <code>rawValue</code> (<code>\"2008\"</code>\u2026), \u044d\u0442\u043e \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442.</p>"},{"location":"states.html","title":"\u0421\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f \u0438 \u0441\u043e\u0431\u044b\u0442\u0438\u044f","text":"<p>\u0414\u0432\u0430 \u043a\u0430\u043d\u0430\u043b\u0430 \u043e\u0431\u0440\u0430\u0442\u043d\u043e\u0439 \u0441\u0432\u044f\u0437\u0438 \u0432\u043e \u0432\u0440\u0435\u043c\u044f \u0441\u043a\u0430\u043d\u0430:</p> <ul> <li><code>ScannerFrameState</code> \u2014 \u0441\u043d\u0438\u043c\u043e\u043a \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f \u00ab\u043a\u0430\u0436\u0434\u044b\u0439 \u043a\u0430\u0434\u0440\u00bb: \u0433\u0435\u043e\u043c\u0435\u0442\u0440\u0438\u044f, \u0444\u0430\u0437\u044b, \u0442\u0435\u043a\u0441\u0442\u044b.   \u041f\u0440\u0438\u0445\u043e\u0434\u0438\u0442 \u0432 <code>onState</code> / <code>onFrameState</code> / \u043e\u0432\u0435\u0440\u043b\u0435\u0439-\u043a\u043b\u043e\u0443\u0436\u0435\u0440\u044b / <code>frameState</code> headless-\u0445\u044d\u043d\u0434\u043b\u0430.</li> <li><code>ScannerEvent</code> \u2014 \u0438\u043c\u0435\u043d\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u044f \u00ab\u043a\u043e\u0433\u0434\u0430 \u0447\u0442\u043e-\u0442\u043e \u043f\u0440\u043e\u0438\u0437\u043e\u0448\u043b\u043e\u00bb: \u043a\u0430\u043c\u0435\u0440\u0430 \u0433\u043e\u0442\u043e\u0432\u0430,   \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u043d\u0430\u0439\u0434\u0435\u043d/\u043f\u043e\u0442\u0435\u0440\u044f\u043d, \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441, \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442, \u043e\u0448\u0438\u0431\u043a\u0430.</li> </ul>"},{"location":"states.html#scannerframestate","title":"<code>ScannerFrameState</code>","text":"\u041f\u043e\u043b\u0435 \u0422\u0438\u043f \u0427\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442 <code>hasCard</code> <code>Bool</code> \u043a\u0430\u0440\u0442\u0430 \u0432\u0438\u0434\u043d\u0430 \u0432 \u044d\u0442\u043e\u043c \u043a\u0430\u0434\u0440\u0435 <code>cardBoundsInView</code> <code>CGRect?</code> / <code>RectF?</code> \u0440\u0430\u043c\u043a\u0430 \u043a\u0430\u0440\u0442\u044b \u0432 \u043a\u043e\u043e\u0440\u0434\u0438\u043d\u0430\u0442\u0430\u0445 \u0432\u044c\u044e (\u043f\u043e\u0432\u043e\u0440\u043e\u0442 \u0438 \u0437\u0430\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u044d\u043a\u0440\u0430\u043d\u0430 \u0443\u0447\u0442\u0435\u043d\u044b); <code>nil</code>, \u043a\u043e\u0433\u0434\u0430 \u043a\u0430\u0440\u0442\u044b \u043d\u0435\u0442 <code>scanRoiInView</code> <code>CGRect?</code> / <code>RectF?</code> \u0430\u043a\u0442\u0438\u0432\u043d\u0430\u044f \u0437\u043e\u043d\u0430 \u0441\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u0432 \u043a\u043e\u043e\u0440\u0434\u0438\u043d\u0430\u0442\u0430\u0445 \u0432\u044c\u044e \u2014 \u0440\u043e\u0432\u043d\u043e \u0442\u043e, \u0447\u0442\u043e \u0432\u0438\u0434\u0438\u0442 \u0434\u0432\u0438\u0436\u043e\u043a; \u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0443\u0435\u0442\u0441\u044f \u043e\u0442\u0440\u0438\u0441\u043e\u0432\u044b\u0432\u0430\u0442\u044c \u0432\u0435\u0441\u044c \u0441\u043a\u0430\u043d <code>confidence</code> <code>Float</code> \u0443\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u0434\u0435\u0442\u0435\u043a\u0446\u0438\u0438 0\u20261 <code>progress</code> <code>Float</code> \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441 \u0441\u0442\u0430\u0431\u0438\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u0437\u0430\u0445\u0432\u0430\u0442\u0430 0\u20261 <code>messageTitle</code> <code>String</code> \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0439 \u0441\u0442\u0430\u0442\u0443\u0441 \u0434\u043b\u044f \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f (\u043f\u0443\u0441\u0442\u0430\u044f \u0441\u0442\u0440\u043e\u043a\u0430 \u2014 \u043d\u0435\u0447\u0435\u0433\u043e \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0442\u044c) <code>messageHint</code> <code>String</code> \u0440\u0430\u0437\u0432\u0451\u0440\u043d\u0443\u0442\u0430\u044f \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430 (\u00ab\u043f\u043e\u0434\u043d\u0435\u0441\u0438\u0442\u0435 \u0431\u043b\u0438\u0436\u0435\u00bb, \u00ab\u0441\u043b\u0438\u0448\u043a\u043e\u043c \u0442\u0435\u043c\u043d\u043e\u00bb\u2026) <code>isAnalyzing</code> <code>Bool</code> \u043a\u043e\u0440\u043e\u0442\u043a\u043e\u0435 \u043e\u043a\u043d\u043e (\u2248400 \u043c\u0441) \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u0432\u0435\u0440\u0441\u0438\u0438 \u043a\u0430\u0440\u0442\u044b \u2014 \u0443\u043c\u0435\u0441\u0442\u043d\u0430 \u0441\u0432\u043e\u044f \u0430\u043d\u0438\u043c\u0430\u0446\u0438\u044f \u00ab\u0430\u043d\u0430\u043b\u0438\u0437\u00bb <code>isScanning</code> <code>Bool</code> \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0435 \u043e\u043a\u043d\u043e \u0441\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f: \u043a\u0430\u0440\u0442\u0430 \u0432 \u043a\u0430\u0434\u0440\u0435, \u0433\u0435\u0439\u0442\u044b \u043d\u0435 \u043e\u0442\u043a\u043b\u043e\u043d\u0438\u043b\u0438; \u0448\u0438\u0440\u0435, \u0447\u0435\u043c <code>isAnalyzing</code> <code>isFinished</code> <code>Bool</code> \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043d (\u0443\u0441\u043f\u0435\u0445\u043e\u043c \u0438\u043b\u0438 \u043d\u0435\u0443\u0434\u0430\u0447\u0435\u0439) <code>isPassed</code> <code>Bool</code> \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043d \u0443\u0441\u043f\u0435\u0448\u043d\u044b\u043c \u0437\u0430\u0445\u0432\u0430\u0442\u043e\u043c; \u043e\u0441\u043c\u044b\u0441\u043b\u0435\u043d \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438 <code>isFinished</code> <code>isCardInGuide</code> / <code>cardInGuide</code> <code>Bool</code> \u043a\u0430\u0440\u0442\u0430 \u043f\u0435\u0440\u0435\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0443\u044e \u0440\u0430\u043c\u043a\u0443 \u2265 80 % (\u043f\u0440\u0438 \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d\u043d\u043e\u0439 \u0440\u0430\u043c\u043a\u0435 \u0432\u0441\u0435\u0433\u0434\u0430 \u00ab\u0432 \u0440\u0430\u043c\u043a\u0435\u00bb) <code>activeColor</code> / <code>activeColorArgb</code> <code>Color</code> / <code>Int</code> \u0433\u043e\u0442\u043e\u0432\u044b\u0439 \u0446\u0432\u0435\u0442 \u0442\u0435\u043a\u0443\u0449\u0435\u0433\u043e \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f, \u0432\u044b\u0432\u0435\u0434\u0435\u043d\u043d\u044b\u0439 \u0438\u0437 \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0433\u043e <code>ScannerStyle</code> \u2014 \u043c\u043e\u0436\u043d\u043e \u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e \u043a\u0440\u0430\u0441\u0438\u0442\u044c \u0441\u0432\u043e\u044e \u0440\u0430\u043c\u043a\u0443 <code>scanStatus</code> <code>ScanStatus</code> \u0442\u0438\u043f\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0441\u0442\u0430\u0442\u0443\u0441 \u043a\u0430\u0434\u0440\u0430 \u2014 \u043c\u0430\u0448\u0438\u043d\u043e\u0447\u0438\u0442\u0430\u0435\u043c\u044b\u0439 \u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442 <code>messageTitle</code>; \u0441\u043c. \u043d\u0438\u0436\u0435 <code>isFingerOccluded</code> <code>Bool</code> \u043a\u0430\u0434\u0440-\u0433\u0435\u0439\u0442 \u0432\u0438\u0434\u0438\u0442 \u043f\u0430\u043b\u0435\u0446 / \u0440\u0443\u043a\u0443 \u043d\u0430 \u0434\u0430\u043d\u043d\u044b\u0445 \u2014 \u0437\u0430\u0445\u0432\u0430\u0442 \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043d, \u0440\u0430\u043c\u043a\u0430 \u043a\u0440\u0430\u0441\u043d\u0430\u044f <code>isShadowed</code> <code>Bool</code> \u043a\u0430\u0434\u0440-\u0433\u0435\u0439\u0442 \u0432\u0438\u0434\u0438\u0442 \u0436\u0451\u0441\u0442\u043a\u0443\u044e \u0442\u0435\u043d\u044c \u043d\u0430 \u043a\u0430\u0440\u0442\u0435 (\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d\u0430 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u2014 \u0441\u043c. \u00ab\u041a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f\u00bb) <code>occludedFieldId</code> <code>Int</code> \u043a\u0430\u043a\u043e\u0435 \u043f\u043e\u043b\u0435 \u0437\u0430\u043a\u0440\u044b\u0442\u043e: <code>6</code> \u2014 \u043d\u043e\u043c\u0435\u0440 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430, <code>12</code> \u2014 MRZ, <code>100</code> \u2014 \u0444\u043e\u0442\u043e \u0432\u043b\u0430\u0434\u0435\u043b\u044c\u0446\u0430 \u0438 \u0442. \u0434.; <code>-1</code> \u2014 \u043d\u0430\u0437\u0432\u0430\u0442\u044c \u043d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c <code>occlusionType</code> <code>OcclusionType</code> \u0447\u0435\u043c \u0437\u0430\u043a\u0440\u044b\u0442\u043e: <code>FINGER</code> / <code>SHADOW</code> / <code>NONE</code> (iOS <code>.finger</code> / <code>.shadow</code> / <code>.none</code>) <p>\u041f\u0443\u0441\u0442\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0434\u043b\u044f \u0438\u043d\u0438\u0446\u0438\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438: <code>ScannerFrameState.empty</code> (iOS) / <code>ScannerFrameState.EMPTY</code> (Android).</p> <p>\u0422\u0438\u043f\u043e\u0432\u0430\u044f \u0440\u0430\u0441\u043a\u043b\u0430\u0434\u043a\u0430 \u0441\u0432\u043e\u0435\u0439 \u043e\u0442\u0440\u0438\u0441\u043e\u0432\u043a\u0438:</p> <pre><code>\u043d\u0435\u0442 \u043a\u0430\u0440\u0442\u044b            \u2192 \u0440\u0430\u043c\u043a\u0430 colorIdle + \u043f\u0440\u0438\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435\nhasCard &amp;&amp; isScanning \u2192 \u0440\u0430\u043c\u043a\u0430 \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0433\u043e \u0446\u0432\u0435\u0442\u0430 + progress\nisAnalyzing           \u2192 \u0430\u043d\u0438\u043c\u0430\u0446\u0438\u044f \u00ab\u0430\u043d\u0430\u043b\u0438\u0437\u00bb\nactiveColor == failure \u2192 \u043a\u0440\u0430\u0441\u043d\u0430\u044f \u0440\u0430\u043c\u043a\u0430 + messageTitle (\u043d\u0435 \u0442\u0430 \u0441\u0442\u043e\u0440\u043e\u043d\u0430 / \u043d\u0435 KG ID / \u043f\u0430\u043b\u0435\u0446 \u043d\u0430 \u0434\u0430\u043d\u043d\u044b\u0445)\nisFinished &amp;&amp; isPassed \u2192 \u0443\u0441\u043f\u0435\u0445: \u0433\u0430\u043b\u043e\u0447\u043a\u0430, \u0432\u0438\u0431\u0440\u0430\u0446\u0438\u044f, \u0437\u0430\u043a\u0440\u044b\u0442\u0438\u0435\n</code></pre>"},{"location":"states.html#scanstatus","title":"<code>ScanStatus</code> \u2014 \u0442\u0438\u043f\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0441\u0442\u0430\u0442\u0443\u0441 \u043a\u0430\u0434\u0440\u0430","text":"<p><code>scanStatus</code> \u2014 \u043c\u0430\u0448\u0438\u043d\u043e\u0447\u0438\u0442\u0430\u0435\u043c\u0430\u044f \u0444\u043e\u0440\u043c\u0430 \u0440\u043e\u0432\u043d\u043e \u0442\u043e\u0439 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0438, \u043a\u043e\u0442\u043e\u0440\u0443\u044e SDK \u043f\u043e\u043a\u0430\u0437\u0430\u043b \u0431\u044b \u0441\u0430\u043c. \u0421\u0442\u0430\u0442\u0443\u0441 \u0438 \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0435 \u0441\u0442\u0440\u043e\u043a\u0438 (<code>messageTitle</code> / <code>messageHint</code> / <code>activeColor</code>) \u0440\u0435\u0437\u043e\u043b\u0432\u044f\u0442\u0441\u044f \u0432 \u043e\u0434\u043d\u043e\u043c \u043c\u0435\u0441\u0442\u0435 \u043e\u0434\u043d\u0438\u043c \u043a\u0430\u0441\u043a\u0430\u0434\u043e\u043c, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0440\u0430\u0437\u043e\u0439\u0442\u0438\u0441\u044c \u043e\u043d\u0438 \u043d\u0435 \u043c\u043e\u0433\u0443\u0442: \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043c\u043e\u0436\u0435\u0442 \u0446\u0435\u043b\u0438\u043a\u043e\u043c \u043f\u0435\u0440\u0435\u0439\u0442\u0438 \u043d\u0430 \u0441\u0432\u043e\u0438 \u0442\u0435\u043a\u0441\u0442\u044b \u0438 \u0441\u0432\u043e\u044e \u043b\u043e\u043a\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044e, \u043d\u0435 \u0440\u0438\u0441\u043a\u0443\u044f \u00ab\u0434\u0432\u0443\u043c\u044f \u0433\u043e\u043b\u043e\u0441\u0430\u043c\u0438\u00bb.</p> <p>\u0417\u0430 \u043a\u0430\u0434\u0440 \u0430\u043a\u0442\u0438\u0432\u0435\u043d \u0440\u043e\u0432\u043d\u043e \u043e\u0434\u0438\u043d \u0441\u0442\u0430\u0442\u0443\u0441 \u2014 \u043f\u0435\u0440\u0432\u044b\u0439 \u0441\u0432\u0435\u0440\u0445\u0443, \u0447\u044c\u0451 \u0443\u0441\u043b\u043e\u0432\u0438\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u043e:</p> <pre><code>Finished &gt; Capturing\n  &gt; WrongSide | NotKgDocument     (\u043e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0435 \u043f\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u0435, \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442\u0441\u044f)\n  &gt; Analyzing\n  &gt; CardOutsideGuide\n  &gt; FlipDocument\n  &gt; Occluded                      (\u043f\u0430\u043b\u0435\u0446 / \u0442\u0435\u043d\u044c \u043d\u0430 \u0434\u0430\u043d\u043d\u044b\u0445 \u2014 \u0437\u0430\u0445\u0432\u0430\u0442 \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043d)\n  &gt; TooClose &gt; TooFar\n  &gt; TooBright &gt; TooDark           (TooDark \u0432\u043e\u0437\u043c\u043e\u0436\u0435\u043d \u0438 \u0431\u0435\u0437 \u043a\u0430\u0440\u0442\u044b \u0432 \u043a\u0430\u0434\u0440\u0435)\n  &gt; HoldSteady\n  &gt; NoCard\n</code></pre> Kotlin Swift \u041a\u043e\u0433\u0434\u0430 <code>NoCard</code> <code>.noCard</code> \u043a\u0430\u0440\u0442\u044b \u0432 \u043a\u0430\u0434\u0440\u0435 \u043d\u0435\u0442 (\u0441\u0442\u0430\u0440\u0442\u043e\u0432\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435) <code>CardOutsideGuide</code> <code>.cardOutsideGuide</code> \u043a\u0430\u0440\u0442\u0430 \u0432\u0438\u0434\u043d\u0430, \u043d\u043e \u043b\u0435\u0436\u0438\u0442 \u043c\u0438\u043c\u043e \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0435\u0439 \u0440\u0430\u043c\u043a\u0438 <code>HoldSteady</code> <code>.holdSteady</code> \u043a\u0430\u0440\u0442\u0430 \u0432\u0435\u0434\u0451\u0442\u0441\u044f, \u0432\u0441\u0451 \u0432 \u043f\u043e\u0440\u044f\u0434\u043a\u0435 \u2014 \u0434\u0435\u0440\u0436\u0438\u0442\u0435 \u0442\u0430\u043a <code>Analyzing</code> <code>.analyzing</code> \u043a\u043e\u0440\u043e\u0442\u043a\u043e\u0435 \u043e\u043a\u043d\u043e \u0440\u0430\u0437\u0431\u043e\u0440\u0430 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0438 \u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u044f <code>WrongSide</code> <code>.wrongSide</code> \u043f\u043e\u043a\u0430\u0437\u0430\u043d\u0430 \u043d\u0435 \u0442\u0430 \u0441\u0442\u043e\u0440\u043e\u043d\u0430, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u0436\u0434\u0451\u0442 \u0444\u043b\u043e\u0443 <code>NotKgDocument</code> <code>.notKgDocument</code> \u0441\u0435\u0440\u0438\u044f \u0432\u0435\u0440\u0434\u0438\u043a\u0442\u043e\u0432 \u00ab\u0432\u0435\u0440\u0441\u0438\u044f \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0430\u00bb <code>FlipDocument</code> <code>.flipDocument</code> \u0434\u0432\u0443\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0438\u0439 \u0444\u043b\u043e\u0443: \u043f\u0435\u0440\u0432\u0430\u044f \u0441\u0442\u043e\u0440\u043e\u043d\u0430 \u043f\u0440\u0438\u043d\u044f\u0442\u0430, \u0436\u0434\u0451\u043c \u043f\u0435\u0440\u0435\u0432\u043e\u0440\u043e\u0442 <code>Occluded</code> <code>.occluded</code> \u043d\u043e\u0432\u043e\u0435 \u0432 2.6.0 \u2014 \u043f\u0430\u043b\u0435\u0446 \u0438\u043b\u0438 \u0442\u0435\u043d\u044c \u043d\u0430 \u0434\u0430\u043d\u043d\u044b\u0445, \u0437\u0430\u0445\u0432\u0430\u0442 \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043d <p>\u0413\u0430\u043b\u0435\u0440\u0435\u044f</p> <p>\u0414\u043b\u044f \u0444\u043e\u0442\u043e \u0438\u0437 \u0433\u0430\u043b\u0435\u0440\u0435\u0438 \u0442\u043e \u0436\u0435 \u0437\u0430\u0441\u043b\u043e\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442 \u0432 \u0432\u0435\u0440\u0434\u0438\u043a\u0442\u0435 \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438: <code>VerifyResult.frontOcclusion</code> / <code>backOcclusion</code> (\u0441 2.6.1) \u2014 \u0441\u043c. \u0412\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f.</p> <p>| <code>TooClose</code> / <code>TooFar</code> | <code>.tooClose</code> / <code>.tooFar</code> | \u0434\u0438\u0441\u0442\u0430\u043d\u0446\u0438\u044f \u0434\u043e \u043a\u0430\u0440\u0442\u044b | | <code>TooBright</code> / <code>TooDark</code> | <code>.tooBright</code> / <code>.tooDark</code> | \u043e\u0441\u0432\u0435\u0449\u0435\u043d\u0438\u0435 | | <code>Capturing</code> | <code>.capturing</code> | \u043a\u0430\u0434\u0440 \u043f\u0440\u0438\u043d\u044f\u0442, \u0438\u0434\u0443\u0442 \u0441\u044a\u0451\u043c\u043a\u0430 \u0438 \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0432\u0430\u043d\u0438\u0435 | | <code>Finished(success)</code> | <code>.finished(success:)</code> | \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043d; \u043d\u0435\u0443\u0434\u0430\u0447\u0430 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442 \u0441\u044e\u0434\u0430 \u0436\u0435 |</p> <p>\u0421\u0442\u0430\u0442\u0443\u0441 \u0443\u0436\u0435 \u0441\u0433\u043b\u0430\u0436\u0435\u043d SDK: \u043e\u043d \u043d\u0430\u0441\u043b\u0435\u0434\u0443\u0435\u0442 \u0433\u0438\u0441\u0442\u0435\u0440\u0435\u0437\u0438\u0441\u044b \u0441\u0432\u043e\u0438\u0445 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432 (\u0443\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u0435 \u043e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0439 \u043f\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u0435, \u0440\u0430\u0437\u043d\u044b\u0435 \u043f\u043e\u0440\u043e\u0433\u0438 \u0432\u0445\u043e\u0434\u0430 \u0438 \u0432\u044b\u0445\u043e\u0434\u0430 \u0443 \u0434\u0438\u0441\u0442\u0430\u043d\u0446\u0438\u0438, \u0434\u0435\u0431\u0430\u0443\u043d\u0441 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043e\u043a, \u043e\u043a\u043d\u043e \u0430\u043d\u0430\u043b\u0438\u0437\u0430). \u0421\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0434\u0435\u0431\u0430\u0443\u043d\u0441 \u043f\u043e\u0432\u0435\u0440\u0445 \u043d\u0435\u0433\u043e \u043d\u0435 \u043d\u0443\u0436\u0435\u043d \u0438 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043e\u0431\u0430\u0432\u0438\u0442 \u0437\u0430\u0434\u0435\u0440\u0436\u043a\u0443.</p> <p>\u0414\u0432\u0435 \u043e\u0433\u043e\u0432\u043e\u0440\u043a\u0438:</p> <ul> <li><code>NotKgDocument</code> \u2014 \u044d\u0442\u043e \u043f\u0440\u043e\u043a\u0441\u0438 \u043f\u043e \u0441\u0435\u0440\u0438\u0438 \u043d\u0435\u0443\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u0445 \u043a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0439, \u0430 \u043d\u0435 \u043a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440   \u0447\u0443\u0436\u0438\u0445 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u043e\u0432: \u0447\u0443\u0436\u043e\u0439 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u0447\u0430\u0449\u0435 \u0432\u043e\u0432\u0441\u0435 \u043d\u0435 \u0434\u0435\u0442\u0435\u043a\u0442\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u043a\u0430\u0440\u0442\u0430 \u0438 \u0434\u0430\u0451\u0442 <code>NoCard</code>.   \u0424\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u0443\u0439\u0442\u0435 \u0442\u0435\u043a\u0441\u0442 \u043e\u0441\u0442\u043e\u0440\u043e\u0436\u043d\u043e.</li> <li><code>FlipDocument</code> \u043d\u0430 iOS \u043e\u0431\u044a\u044f\u0432\u043b\u044f\u0435\u0442 \u0432\u0430\u0448 \u0444\u043b\u043e\u0443 (<code>MergenScannerView(awaitingFlip:)</code> \u0438\u043b\u0438   <code>MergenScannerStateHandle.setAwaitingFlip(_:)</code>): \u0448\u0430\u0433 \u043f\u0435\u0440\u0435\u0432\u043e\u0440\u043e\u0442\u0430 \u0438\u0434\u0451\u0442 \u043f\u0440\u0438 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u043e\u0439   \u043a\u0430\u043c\u0435\u0440\u0435, \u043a\u0430\u0434\u0440\u043e\u0432 \u0432 \u044d\u0442\u043e\u0442 \u043c\u043e\u043c\u0435\u043d\u0442 \u043d\u0435\u0442. \u041d\u0430 Android \u0434\u0432\u0443\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0438\u0439 \u0440\u0435\u0436\u0438\u043c \u0432\u0435\u0434\u0451\u0442 \u0441\u0430\u043c SDK.</li> </ul> <p>\u041b\u043e\u043c\u0430\u044e\u0449\u0435\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 2.6.0 \u2014 \u043d\u043e\u0432\u044b\u0439 \u043a\u0435\u0439\u0441 <code>Occluded</code> / <code>.occluded</code></p> <p>\u041a\u0435\u0439\u0441 \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d \u0432 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044e\u0449\u0435\u0435 \u043f\u0435\u0440\u0435\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0435, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0438\u0441\u0447\u0435\u0440\u043f\u044b\u0432\u0430\u044e\u0449\u0438\u0435 <code>when</code> (Kotlin) \u0438 <code>switch</code> (Swift) \u043f\u0435\u0440\u0435\u0441\u0442\u0430\u043d\u0443\u0442 \u043a\u043e\u043c\u043f\u0438\u043b\u0438\u0440\u043e\u0432\u0430\u0442\u044c\u0441\u044f, \u043f\u043e\u043a\u0430 \u0432 \u043d\u0438\u0445 \u043d\u0435 \u043f\u043e\u044f\u0432\u0438\u0442\u0441\u044f \u043d\u043e\u0432\u0430\u044f \u0432\u0435\u0442\u043a\u0430. \u042d\u0442\u043e \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e\u0433\u043e API \u0432 2.6.0.</p> <p>\u0420\u0430\u043d\u044c\u0448\u0435 \u043d\u0430 \u0442\u0430\u043a\u0438\u0445 \u043a\u0430\u0434\u0440\u0430\u0445 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u043b <code>HoldSteady</code> (\u00ab\u0434\u0435\u0440\u0436\u0438\u0442\u0435 \u043d\u0435\u043f\u043e\u0434\u0432\u0438\u0436\u043d\u043e\u00bb) \u2014 \u043f\u0440\u0438 \u043a\u0440\u0430\u0441\u043d\u043e\u0439 \u0440\u0430\u043c\u043a\u0435 \u0438 \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043a\u0438 \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c \u0437\u0430\u0445\u0432\u0430\u0442\u0435 \u044d\u0442\u043e \u043f\u0440\u044f\u043c\u043e \u0432\u0432\u043e\u0434\u0438\u043b\u043e \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f \u0432 \u0437\u0430\u0431\u043b\u0443\u0436\u0434\u0435\u043d\u0438\u0435, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043a\u0435\u0439\u0441 \u0438 \u043f\u043e\u043d\u0430\u0434\u043e\u0431\u0438\u043b\u0441\u044f.</p> KotlinSwift <pre><code>val hint = when (val s = state.scanStatus) {\n    ScanStatus.NoCard      -&gt; \"\u041d\u0430\u0432\u0435\u0434\u0438\u0442\u0435 \u043a\u0430\u043c\u0435\u0440\u0443 \u043d\u0430 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\"\n    ScanStatus.TooFar      -&gt; \"\u041f\u043e\u0434\u043d\u0435\u0441\u0438\u0442\u0435 \u0431\u043b\u0438\u0436\u0435\"\n    // \u041d\u041e\u0412\u041e\u0415 \u0432 2.6.0: \u043f\u0430\u043b\u0435\u0446 \u0438\u043b\u0438 \u0442\u0435\u043d\u044c \u043d\u0430 \u0434\u0430\u043d\u043d\u044b\u0445, \u0437\u0430\u0445\u0432\u0430\u0442 \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043d\n    ScanStatus.Occluded    -&gt; when (state.occlusionType) {\n        OcclusionType.FINGER -&gt; \"\u0423\u0431\u0435\u0440\u0438\u0442\u0435 \u043f\u0430\u043b\u0435\u0446 \u0441 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\"\n        OcclusionType.SHADOW -&gt; \"\u0423\u0431\u0435\u0440\u0438\u0442\u0435 \u0442\u0435\u043d\u044c\"\n        OcclusionType.NONE   -&gt; \"\"\n    }\n    is ScanStatus.Finished -&gt; if (s.success) \"\" else \"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u043e\u0442\u0441\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u0442\u044c\"\n    else                   -&gt; \"\"\n}\n</code></pre> <pre><code>let hint: String\nswitch state.scanStatus {\ncase .noCard: hint = \"\u041d\u0430\u0432\u0435\u0434\u0438\u0442\u0435 \u043a\u0430\u043c\u0435\u0440\u0443 \u043d\u0430 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\"\ncase .tooFar: hint = \"\u041f\u043e\u0434\u043d\u0435\u0441\u0438\u0442\u0435 \u0431\u043b\u0438\u0436\u0435\"\n// \u041d\u041e\u0412\u041e\u0415 \u0432 2.6.0: \u043f\u0430\u043b\u0435\u0446 \u0438\u043b\u0438 \u0442\u0435\u043d\u044c \u043d\u0430 \u0434\u0430\u043d\u043d\u044b\u0445, \u0437\u0430\u0445\u0432\u0430\u0442 \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043d\ncase .occluded:\n    switch state.occlusionType {\n    case .finger: hint = \"\u0423\u0431\u0435\u0440\u0438\u0442\u0435 \u043f\u0430\u043b\u0435\u0446 \u0441 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\"\n    case .shadow: hint = \"\u0423\u0431\u0435\u0440\u0438\u0442\u0435 \u0442\u0435\u043d\u044c\"\n    case .none:   hint = \"\"\n    }\ncase .finished(let success): hint = success ? \"\" : \"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u043e\u0442\u0441\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u0442\u044c\"\ndefault: hint = \"\"\n}\n</code></pre> <p>\u0412\u0435\u0442\u043a\u0430 <code>else</code> / <code>default</code> \u0441\u043f\u0430\u0441\u0430\u0435\u0442 \u043e\u0442 \u043e\u0448\u0438\u0431\u043a\u0438 \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0446\u0438\u0438, \u043d\u043e \u043d\u0435 \u043e\u0442 \u043c\u043e\u043b\u0447\u0430\u043b\u0438\u0432\u043e\u0433\u043e UI: \u043f\u043e\u043a\u0430 <code>Occluded</code> \u043f\u043e\u043f\u0430\u0434\u0430\u0435\u0442 \u0432 \u043d\u0435\u0451, \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044c \u043f\u0440\u0438 \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c \u0437\u0430\u0445\u0432\u0430\u0442\u0435 \u043d\u0435 \u0443\u0432\u0438\u0434\u0438\u0442 \u043d\u0438\u0447\u0435\u0433\u043e. \u041c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u043e\u0431\u0440\u0430\u0442\u043d\u043e \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u0438\u043c\u044b\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442 \u2014 \u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u043e\u0431\u0449\u0443\u044e \u0432\u0435\u0442\u043a\u0443 \u0438 \u0441\u043c\u043e\u0442\u0440\u0435\u0442\u044c \u043d\u0430 \u043f\u043e\u043b\u044f \u0442\u043e\u0433\u043e \u0436\u0435 \u043a\u0430\u0434\u0440\u0430 (<code>isFingerOccluded</code>, <code>isShadowed</code>); \u0433\u043e\u0442\u043e\u0432\u0430\u044f \u0440\u0443\u0441\u0441\u043a\u0430\u044f \u0441\u0442\u0440\u043e\u043a\u0430 \u0441 \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u0435\u043c \u0437\u0430\u043a\u0440\u044b\u0442\u043e\u0433\u043e \u043f\u043e\u043b\u044f \u0443\u0436\u0435 \u043b\u0435\u0436\u0438\u0442 \u0432 <code>messageTitle</code>.</p>"},{"location":"states.html#scannerevent","title":"<code>ScannerEvent</code>","text":"\u0421\u043e\u0431\u044b\u0442\u0438\u0435 \u0414\u0430\u043d\u043d\u044b\u0435 \u041a\u043e\u0433\u0434\u0430 <code>cameraReady</code> / <code>CameraReady</code> \u2014 \u043a\u0430\u043c\u0435\u0440\u0430 \u043f\u0440\u0438\u0432\u044f\u0437\u0430\u043d\u0430 \u0438 \u043e\u0442\u0434\u0430\u0451\u0442 \u043a\u0430\u0434\u0440\u044b (\u043f\u043e\u0432\u0442\u043e\u0440\u044f\u0435\u0442\u0441\u044f \u043f\u043e\u0441\u043b\u0435 \u0432\u043e\u0437\u0432\u0440\u0430\u0442\u0430 \u0438\u0437 \u0444\u043e\u043d\u0430) <code>documentDetected</code> / <code>DocumentDetected</code> <code>bounds</code> \u0432 \u043a\u043e\u043e\u0440\u0434\u0438\u043d\u0430\u0442\u0430\u0445 \u0432\u044c\u044e \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u043f\u043e\u044f\u0432\u0438\u043b\u0441\u044f \u0432 \u043a\u0430\u0434\u0440\u0435 <code>DocumentLost</code> (Android) \u0441\u0435\u043a\u0443\u043d\u0434\u044b \u0441 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0433\u043e \u043f\u043e\u044f\u0432\u043b\u0435\u043d\u0438\u044f \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u043f\u0440\u043e\u043f\u0430\u043b \u0438 \u043d\u0435 \u0432\u0435\u0440\u043d\u0443\u043b\u0441\u044f \u0437\u0430 1.2 \u0441 <code>processing</code> / <code>Processing</code> <code>progress</code> \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441 \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u0441\u044f \u043d\u0430 \u2265 0.1 (\u0447\u0430\u0441\u0442\u043e\u0442\u0430 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u0430 \u0434\u043b\u044f UI) <code>success</code> / <code>Success</code> \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0441\u043a\u0430\u043d\u0430 \u0438\u0442\u043e\u0433 \u2014 \u043d\u0435\u0443\u0434\u0430\u0447\u043d\u044b\u0439 \u0437\u0430\u0445\u0432\u0430\u0442 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442 \u0441\u044e\u0434\u0430 \u0436\u0435: \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0439\u0442\u0435 <code>success</code> \u0443 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430 <code>error</code> / <code>Error</code> \u043e\u0448\u0438\u0431\u043a\u0430 \u0441\u0431\u043e\u0439 \u0438\u043d\u0438\u0446\u0438\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438/\u0440\u0430\u043d\u0442\u0430\u0439\u043c\u0430, \u043e\u0442\u043a\u0430\u0437 \u0432 \u0434\u043e\u0441\u0442\u0443\u043f\u0435 \u043a \u043a\u0430\u043c\u0435\u0440\u0435 <p>\u0413\u0434\u0435 \u043f\u043e\u0434\u043f\u0438\u0441\u044b\u0432\u0430\u0442\u044c\u0441\u044f:</p> iOSAndroid <pre><code>// \u041a\u043b\u043e\u0443\u0436\u0435\u0440\nMergenScannerView(..., onEvent: { event in ... }) { state in ... }\n\n// \u0418\u043b\u0438 \u043f\u043e\u0442\u043e\u043a (headless-\u0445\u044d\u043d\u0434\u043b \u0438 UIKit-\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u043b\u0435\u0440)\nfor await event in handle.events { ... }\n</code></pre> <p><code>events</code> \u2014 <code>AsyncStream</code>; \u043a\u0430\u0436\u0434\u043e\u0435 \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u043a \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0443 \u0441\u043e\u0437\u0434\u0430\u0451\u0442 \u043d\u043e\u0432\u044b\u0439 \u0441\u0442\u0440\u0438\u043c \u2014 \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u0435 \u0435\u0433\u043e \u043e\u0434\u0438\u043d \u0440\u0430\u0437 \u0438 \u0434\u0435\u0440\u0436\u0438\u0442\u0435.</p> <pre><code>// \u041a\u043b\u043e\u0443\u0436\u0435\u0440\nMergenScannerView(..., onEvent = { event -&gt; ... }, ...)\n\n// \u0418\u043b\u0438 \u043f\u043e\u0442\u043e\u043a (Compose-\u0432\u044c\u044e, XML-\u0432\u044c\u044e, headless-\u0445\u044d\u043d\u0434\u043b)\nscope.launch { handle.events.collect { event -&gt; ... } }\n</code></pre> <p><code>events</code> \u2014 hot <code>Flow</code>: \u0441\u043e\u0431\u044b\u0442\u0438\u044f \u0431\u0435\u0437 \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0433\u043e \u043f\u043e\u0434\u043f\u0438\u0441\u0447\u0438\u043a\u0430 \u0442\u0435\u0440\u044f\u044e\u0442\u0441\u044f \u2014 \u0441\u043e\u0431\u0438\u0440\u0430\u0439\u0442\u0435, \u043f\u043e\u043a\u0430 \u044d\u043a\u0440\u0430\u043d \u0432\u0438\u0434\u0435\u043d.</p>"},{"location":"states.html#_2","title":"\u041e\u0448\u0438\u0431\u043a\u0438 \u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430","text":"iOSAndroid <pre><code>public enum MergenError: Error {\n    case licenseEmpty            // \u00ab\u041b\u0438\u0446\u0435\u043d\u0437\u0438\u044f \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u0430\u2026\u00bb\n    case engineInitFailed        // \u00ab\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0438\u043d\u0438\u0446\u0438\u0430\u043b\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0432\u0430\u043d\u0438\u0435\u2026\u00bb\n    case cameraPermissionDenied  // \u00ab\u041d\u0435\u0442 \u0434\u043e\u0441\u0442\u0443\u043f\u0430 \u043a \u043a\u0430\u043c\u0435\u0440\u0435\u2026\u00bb\n    public var userMessage: String { get }   // \u0433\u043e\u0442\u043e\u0432\u044b\u0439 \u0440\u0443\u0441\u0441\u043a\u0438\u0439 \u0442\u0435\u043a\u0441\u0442\n}\n</code></pre> <pre><code>sealed interface MergenException { val userMessage: String }  // \u0433\u043e\u0442\u043e\u0432\u044b\u0439 \u0440\u0443\u0441\u0441\u043a\u0438\u0439 \u0442\u0435\u043a\u0441\u0442\n\nclass CameraPermissionDeniedException : SecurityException, MergenException\nclass UnsupportedAbiException : IllegalStateException, MergenException {\n    val deviceAbis: List&lt;String&gt;\n    val supportedAbis: List&lt;String&gt;\n}\n\n// \u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0414\u041e \u043e\u0442\u043a\u0440\u044b\u0442\u0438\u044f \u0441\u043a\u0430\u043d\u0435\u0440\u0430 (SDK \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 64-\u0431\u0438\u0442\u043d\u044b\u0445 ARM):\nMergen.isDeviceSupported(): Boolean\nMergen.unsupportedDeviceReason(): UnsupportedAbiException?\n</code></pre> <p>\u0415\u0441\u043b\u0438 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u044f\u043c\u0438 \u0441\u0430\u043c\u043e (<code>handlePermissionsInternally = false</code> \u0432 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438), SDK \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u044b\u0439 \u0437\u0430\u043f\u0440\u043e\u0441 \u043a\u0430\u043c\u0435\u0440\u044b: \u043f\u0440\u0438 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0438 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043f\u0440\u0438\u0434\u0451\u0442 <code>cameraPermissionDenied</code> \u0432 <code>onError</code> \u0438 \u0441\u043e\u0431\u044b\u0442\u0438\u0435 <code>error</code>.</p>"},{"location":"verify.html","title":"\u0412\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u0434\u0432\u0443\u0445 \u0441\u0442\u043e\u0440\u043e\u043d","text":"<p>\u0421\u0432\u0435\u0440\u043a\u0430 \u043b\u0438\u0446\u0435\u0432\u043e\u0439 \u0438 \u043e\u0431\u043e\u0440\u043e\u0442\u043d\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u043e\u0434\u043d\u0438\u043c \u0432\u044b\u0437\u043e\u0432\u043e\u043c <code>verify</code>. \u0412\u0445\u043e\u0434 \u2014 \u043b\u0438\u0431\u043e \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043d\u043d\u044b\u0439 \u0441\u043a\u0430\u043d \u043a\u0430\u043c\u0435\u0440\u044b (<code>.scan</code>), \u043b\u0438\u0431\u043e \u0441\u044b\u0440\u043e\u0435 \u0444\u043e\u0442\u043e (<code>.image</code>), \u0432 \u043b\u044e\u0431\u043e\u0439 \u043a\u043e\u043c\u0431\u0438\u043d\u0430\u0446\u0438\u0438.</p>"},{"location":"verify.html#_2","title":"\u0422\u043e\u0447\u043a\u0438 \u0432\u0445\u043e\u0434\u0430","text":"iOSAndroid <pre><code>// \u0420\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0443\u0435\u043c\u0430\u044f: \u0443\u043d\u0438\u0432\u0435\u0440\u0441\u0430\u043b\u044c\u043d\u044b\u0435 \u0432\u0445\u043e\u0434\u044b\nlet result = try await MergenSDK.verify(\n    front:   .scan(frontScan),          // \u0438\u043b\u0438 .image(uiImage)\n    back:    .scan(backScan),\n    license: license,\n    strict:  false\n)\n\n// \u041f\u043e \u0434\u0432\u0443\u043c \u0444\u043e\u0442\u043e\u0433\u0440\u0430\u0444\u0438\u044f\u043c\nlet result = try await MergenSDK.verify(front: frontImage, back: backImage, license: license)\n\n// \u041c\u0433\u043d\u043e\u0432\u0435\u043d\u043d\u0430\u044f stateless-\u0441\u0432\u0435\u0440\u043a\u0430 \u0434\u0432\u0443\u0445 \u0441\u043a\u0430\u043d\u043e\u0432 \u043a\u0430\u043c\u0435\u0440\u044b (~1 \u043c\u0441, \u0431\u0435\u0437 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0433\u043e OCR)\nlet result = try await MergenSDK.verifyCards(front: frontScan, back: backScan, license: license)\n</code></pre> <pre><code>// \u0420\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0443\u0435\u043c\u0430\u044f: \u0443\u043d\u0438\u0432\u0435\u0440\u0441\u0430\u043b\u044c\u043d\u044b\u0435 \u0432\u0445\u043e\u0434\u044b (suspend)\nval result = Mergen.verify(\n    context = context,\n    front   = MergenSideInput.Scan(frontScan),   // \u0438\u043b\u0438 MergenSideInput.Image(bitmap)\n    back    = MergenSideInput.Scan(backScan),\n    license = license,\n    strict  = false,\n)\n\n// \u041f\u043e \u0434\u0432\u0443\u043c \u0444\u043e\u0442\u043e\u0433\u0440\u0430\u0444\u0438\u044f\u043c (suspend)\nval result = Mergen.verify(context, frontBitmap, backBitmap, license)\n\n// \u041c\u0433\u043d\u043e\u0432\u0435\u043d\u043d\u0430\u044f stateless-\u0441\u0432\u0435\u0440\u043a\u0430 \u0434\u0432\u0443\u0445 \u0441\u043a\u0430\u043d\u043e\u0432 \u043a\u0430\u043c\u0435\u0440\u044b (~1 \u043c\u0441, \u0431\u0435\u0437 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0433\u043e OCR)\nval result = Mergen.verifyCards(context, frontScan, backScan, license)\n</code></pre> <p>\u041a\u0430\u043a \u0432\u044b\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u043f\u0443\u0442\u044c \u0432 \u0443\u043d\u0438\u0432\u0435\u0440\u0441\u0430\u043b\u044c\u043d\u043e\u043c <code>verify</code>:</p> <ul> <li>\u043e\u0431\u0435 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u2014 \u0441\u043a\u0430\u043d\u044b \u043a\u0430\u043c\u0435\u0440\u044b \u0441\u043e \u0441\u043d\u0438\u043c\u043a\u0430\u043c\u0438 (<code>hasSideSnapshot == true</code>) \u2192 \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u043c\u0433\u043d\u043e\u0432\u0435\u043d\u043d\u0430\u044f   stateless-\u0441\u0432\u0435\u0440\u043a\u0430; \u0435\u0441\u043b\u0438 \u0432\u0435\u0440\u0434\u0438\u043a\u0442 \u043e\u0434\u043d\u043e\u0437\u043d\u0430\u0447\u0435\u043d (\u0443\u0441\u043f\u0435\u0445 \u0438\u043b\u0438 \u044f\u0432\u043d\u043e\u0435 \u043d\u0435\u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u043e\u0432) \u2014   \u043e\u043d \u0438 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f; \u0438\u043d\u0430\u0447\u0435 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0435\u0442\u0441\u044f \u043f\u043e\u043b\u043d\u044b\u0439 OCR-\u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d \u043f\u043e \u043a\u0440\u043e\u043f\u0430\u043c;</li> <li>\u043b\u044e\u0431\u0430\u044f \u0441\u0442\u043e\u0440\u043e\u043d\u0430 <code>.image</code> \u2192 \u043f\u043e\u043b\u043d\u044b\u0439 OCR-\u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d (\u0441\u0435\u043a\u0443\u043d\u0434\u044b): \u0432\u044b\u0437\u044b\u0432\u0430\u0439\u0442\u0435 \u0438\u0437 \u0444\u043e\u043d\u043e\u0432\u043e\u0439 \u0437\u0430\u0434\u0430\u0447\u0438,   \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0439\u0442\u0435 \u0438\u043d\u0434\u0438\u043a\u0430\u0442\u043e\u0440, UI \u043e\u0431\u043d\u043e\u0432\u043b\u044f\u0439\u0442\u0435 \u043d\u0430 \u0433\u043b\u0430\u0432\u043d\u043e\u043c \u043f\u043e\u0442\u043e\u043a\u0435.</li> </ul> <p><code>strict: true</code> \u0443\u0436\u0435\u0441\u0442\u043e\u0447\u0430\u0435\u0442 \u0432\u0435\u0440\u0434\u0438\u043a\u0442: \u0443\u0441\u043f\u0435\u0445 \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0443\u0441\u043f\u0435\u0445\u043e\u043c \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438 \u0441\u0442\u0440\u043e\u0433\u043e\u043c \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0438 \u00ab\u043e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u00bb.</p>"},{"location":"verify.html#configure","title":"\u0422\u043e\u043d\u043a\u0430\u044f \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430 (<code>configure</code>)","text":"<p>\u041e\u0431\u0430 <code>verify</code> \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0442 \u043d\u0435\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0431\u043b\u043e\u043a \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438:</p> \u041f\u043e\u043b\u0435 \u041f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u0427\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442 <code>leanFields</code> <code>true</code> \u0447\u0438\u0442\u0430\u0442\u044c \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u043e\u043c\u0435\u0440, \u041f\u0418\u041d \u0438 MRZ <code>strictSameDocument</code> <code>false</code> \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u0442\u044c \u0441\u0442\u0440\u043e\u0433\u0438\u0439 \u0432\u0435\u0440\u0434\u0438\u043a\u0442 SAME_DOCUMENT (\u0431\u0435\u0437 \u0434\u043e\u043f\u0443\u0441\u043a\u0430 \u043d\u0430 \u0441\u043f\u043e\u0440\u043d\u043e\u0435 \u043f\u043e\u043b\u0435) <code>retryBudget</code> iOS 15 / Android 12 \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0440\u0430\u0437 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e \u043f\u043e\u0434\u0430\u0432\u0430\u0442\u044c \u043a\u0430\u0436\u0434\u043e\u0435 \u0444\u043e\u0442\u043e \u0432 \u0434\u0435\u0442\u0435\u043a\u0446\u0438\u044e: \u0431\u043e\u043b\u044c\u0448\u0435 \u2014 \u0432\u044b\u0448\u0435 \u043f\u043e\u043b\u043d\u043e\u0442\u0430, \u043c\u0435\u0434\u043b\u0435\u043d\u043d\u0435\u0435 <code>debugLogging</code> <code>false</code> \u043f\u043e\u0434\u0440\u043e\u0431\u043d\u044b\u0439 \u043b\u043e\u0433 <code>diagnosticCallback</code> <code>nil</code> \u043f\u043e\u0448\u0430\u0433\u043e\u0432\u0430\u044f \u0434\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u043a\u0430 \u0431\u0435\u0437 \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445; \u0432\u044b\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432 \u0444\u043e\u043d\u043e\u0432\u043e\u043c \u043f\u043e\u0442\u043e\u043a\u0435 <code>useUnifiedDetector</code> <code>true</code> \u0434\u043e\u043b\u0436\u0435\u043d \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u0442\u044c \u0441\u043e \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435\u043c \u0432 <code>warmUp</code>/<code>preload</code>"},{"location":"verify.html#verifyresult","title":"<code>VerifyResult</code>","text":"\u041f\u043e\u043b\u0435 \u0422\u0438\u043f \u0427\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u0435\u0442 <code>status</code> <code>VerifyStatus</code> \u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u0432\u0435\u0440\u0434\u0438\u043a\u0442 (\u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u043d\u0438\u0436\u0435) <code>verifyId</code> <code>String</code> \u0438\u0442\u043e\u0433\u043e\u0432\u044b\u0439 \u043d\u043e\u043c\u0435\u0440 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430 \u043f\u043e\u0441\u043b\u0435 \u043a\u0440\u043e\u0441\u0441-\u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u0438 \u0441\u0442\u043e\u0440\u043e\u043d (\u043f\u0443\u0441\u0442\u0430\u044f \u0441\u0442\u0440\u043e\u043a\u0430 \u2014 \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d) <code>verifyPin</code> <code>String</code> \u0438\u0442\u043e\u0433\u043e\u0432\u044b\u0439 \u041f\u0418\u041d \u043f\u043e\u0441\u043b\u0435 \u043a\u0440\u043e\u0441\u0441-\u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u0438 <code>docNumber</code> / <code>pin</code> <code>String?</code> \u043e\u0431\u044a\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u044b\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u043f\u043e\u0441\u043b\u0435 \u0441\u0432\u0435\u0440\u043a\u0438 \u0432\u0438\u0437\u0443\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0447\u0442\u0435\u043d\u0438\u044f \u0441 MRZ <code>mrzDocNumber</code> / <code>mrzPin</code> <code>String?</code> \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f, \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043d\u043d\u044b\u0435 \u0438\u0437 MRZ <code>mrzFull</code> <code>String?</code> \u0441\u0442\u0440\u043e\u043a\u0438 MRZ \u0447\u0435\u0440\u0435\u0437 <code>\\n</code> <code>mrzConfirmed</code> <code>Bool</code> MRZ \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043d \u0438 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u044b\u0435 \u0441\u0443\u043c\u043c\u044b \u0441\u043e\u0448\u043b\u0438\u0441\u044c <code>sameDocument</code> <code>SameDocumentVerdict</code> \u0432\u0435\u0440\u0434\u0438\u043a\u0442 \u00ab\u043e\u0434\u043d\u0430 \u043b\u0438 \u044d\u0442\u043e \u043a\u0430\u0440\u0442\u0430\u00bb <code>frontIssue</code> / <code>backIssue</code> <code>VerifySideIssue?</code> \u0447\u0442\u043e \u043d\u0435 \u0442\u0430\u043a \u0441 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u043e\u0439 <code>frontOcclusion</code> / <code>backOcclusion</code> <code>OcclusionType</code> \u043d\u043e\u0432\u043e\u0435 \u0432 2.6.1 \u2014 \u0437\u0430\u0441\u043b\u043e\u043d\u0435\u043d\u0438\u0435 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u043f\u043e \u0432\u0435\u0440\u0434\u0438\u043a\u0442\u0443 \u043a\u0430\u0434\u0440-\u0433\u0435\u0439\u0442\u0430: <code>finger</code> / <code>shadow</code> / <code>none</code>; \u0437\u0430\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u043d\u0430 image-\u0432\u0445\u043e\u0434\u0430\u0445 (\u0433\u0430\u043b\u0435\u0440\u0435\u044f) <code>frontPhoto</code> / <code>backPhoto</code> <code>UIImage?</code> / <code>Bitmap?</code> \u0432\u044b\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0435 \u043a\u0440\u043e\u043f\u044b \u043a\u0430\u0440\u0442\u044b \u2014 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0439\u0442\u0435 \u0438\u0445, \u0430 \u043d\u0435 \u0438\u0441\u0445\u043e\u0434\u043d\u044b\u0435 \u0444\u043e\u0442\u043e <code>mrzMatch</code> \u0441\u043f\u0438\u0441\u043e\u043a \u043f\u043e-\u043f\u043e\u043b\u0435\u0432\u043e\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0432\u0438\u0437\u0443\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0447\u0442\u0435\u043d\u0438\u044f \u0441 MRZ (\u043f\u043e\u043b\u0435, \u043e\u0431\u0430 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f, \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435, \u0447\u0435\u043a\u0441\u0443\u043c\u043c\u0430) <code>frontDetectedGeneration</code> / <code>backDetectedGeneration</code> <code>MergenDocGeneration?</code> \u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u0435 \u043a\u0430\u0436\u0434\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b <code>generationMismatch</code> \u043f\u0430\u0440\u0430 \u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u0439 \u0438\u043b\u0438 <code>nil</code> \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430 \u00ab\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e, \u0434\u0432\u0435 \u0440\u0430\u0437\u043d\u044b\u0435 \u043a\u0430\u0440\u0442\u044b\u00bb \u2014 \u0442\u0440\u0430\u043a\u0442\u043e\u0432\u0430\u0442\u044c \u043a\u0430\u043a \u043f\u0440\u0435\u0434\u0443\u043f\u0440\u0435\u0436\u0434\u0435\u043d\u0438\u0435, \u043d\u0435 \u043a\u0430\u043a \u043e\u0442\u043a\u0430\u0437 <code>message</code> / <code>messageEn</code> <code>String?</code> \u0433\u043e\u0442\u043e\u0432\u044b\u0439 \u0442\u0435\u043a\u0441\u0442 \u0438\u0442\u043e\u0433\u0430 (\u0440\u0443\u0441/\u0430\u043d\u0433\u043b); <code>nil</code> \u043f\u0440\u0438 \u0443\u0441\u043f\u0435\u0445\u0435 <p>\u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043d\u0430 iOS: <code>docBadge</code> / <code>pinBadge</code> (<code>ConfidenceBadge</code>: <code>missing / uncertain / probable / confirmed</code>) \u2014 \u0433\u043e\u0442\u043e\u0432\u044b\u0435 \u0431\u0435\u0439\u0434\u0436\u0438 \u0443\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u0434\u043b\u044f UI, \u0438 <code>frontFieldAvailability</code> / <code>backFieldAvailability</code> \u2014 \u043a\u0430\u043a\u0438\u0435 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0438 \u0434\u0430\u043d\u043d\u044b\u0445 \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043a\u0438 \u0435\u0441\u0442\u044c \u0443 \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u043d\u043d\u043e\u0433\u043e \u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u044f (\u043d\u043e\u043c\u0435\u0440 \u043d\u0430 \u0441\u0442\u043e\u0440\u043e\u043d\u0435, \u041f\u0418\u041d \u043d\u0430 \u0441\u0442\u043e\u0440\u043e\u043d\u0435, MRZ).</p>"},{"location":"verify.html#_3","title":"\u0421\u0442\u0430\u0442\u0443\u0441\u044b","text":"<p><code>VerifyStatus</code>:</p> iOS Android \u0421\u043c\u044b\u0441\u043b <code>.verified</code> <code>VERIFIED</code> \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0441\u0432\u0435\u0440\u0435\u043d\u044b, MRZ \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043d, \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u044b\u0435 \u0441\u0443\u043c\u043c\u044b \u0441\u043e\u0448\u043b\u0438\u0441\u044c <code>.verifiedVisual</code> <code>VERIFIED_VISUAL</code> \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0441\u043e\u0432\u043f\u0430\u043b\u0438 \u043f\u043e \u043d\u043e\u043c\u0435\u0440\u0443 (\u0438 \u041f\u0418\u041d \u0434\u043b\u044f 2008), MRZ \u043d\u0435 \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043d \u2014 \u044d\u0442\u043e \u043d\u0435 \u043e\u0442\u043a\u0430\u0437 <code>.failedFront</code> <code>FAILED_FRONT</code> \u043b\u0438\u0446\u0435\u0432\u0430\u044f \u0441\u0442\u043e\u0440\u043e\u043d\u0430 \u043d\u0435 \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043d\u0430 <code>.failedBack</code> <code>FAILED_BACK</code> \u043e\u0431\u043e\u0440\u043e\u0442\u043d\u0430\u044f \u0441\u0442\u043e\u0440\u043e\u043d\u0430 \u043d\u0435 \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043d\u0430 / \u043d\u0435\u0442 MRZ \u0438 \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u044f \u0441\u0442\u043e\u0440\u043e\u043d <code>.failed</code> <code>FAILED</code> \u043d\u0435\u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u043e\u0432 \u0438\u043b\u0438 \u0436\u0451\u0441\u0442\u043a\u0438\u0439 \u043e\u0442\u043a\u0430\u0437 <code>.unknown</code> <code>UNKNOWN</code> \u0432\u0435\u0440\u0434\u0438\u043a\u0442 \u043d\u0435 \u0441\u0444\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u0430\u043d <p>\u0423\u0434\u043e\u0431\u043d\u044b\u0439 \u043f\u0440\u0438\u0437\u043d\u0430\u043a \u043d\u0430 iOS: <code>status.isSuccess</code> (<code>verified || verifiedVisual</code>).</p> <p><code>VerifySideIssue</code>:</p> \u0417\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0421\u043c\u044b\u0441\u043b <code>.wrongSide</code> / <code>WRONG_SIDE</code> \u0432 \u0441\u043b\u043e\u0442\u0435 \u043d\u0435 \u0442\u0430 \u0441\u0442\u043e\u0440\u043e\u043d\u0430 (\u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0441\u043b\u0443\u0447\u0430\u0439 \u00ab\u043e\u0431\u0430 \u0444\u043e\u0442\u043e \u2014 \u043b\u0438\u0446\u0435\u0432\u0430\u044f\u00bb) <code>.notRecognized</code> / <code>NOT_RECOGNIZED</code> \u0441\u0442\u043e\u0440\u043e\u043d\u0430 \u043d\u0435 \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u043d\u0430 \u043a\u0430\u043a KG ID"},{"location":"verify.html#261","title":"\u041f\u0440\u0438\u0447\u0438\u043d\u0430 \u043e\u0442\u043a\u0430\u0437\u0430: \u043f\u0430\u043b\u0435\u0446 \u0438\u043b\u0438 \u0442\u0435\u043d\u044c (2.6.1)","text":"<p>\u041a\u043e\u0433\u0434\u0430 \u0441\u0442\u043e\u0440\u043e\u043d\u0430 \u043f\u043e\u0434\u0430\u043d\u0430 \u0438\u0437\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u0435\u043c (\u0433\u0430\u043b\u0435\u0440\u0435\u044f) \u0438 \u043a\u0430\u0434\u0440-\u0433\u0435\u0439\u0442 \u0432\u0438\u0434\u0438\u0442 \u0437\u0430\u0441\u043b\u043e\u043d\u0435\u043d\u0438\u0435, <code>frontOcclusion</code> / <code>backOcclusion</code> \u043d\u0430\u0437\u044b\u0432\u0430\u044e\u0442 \u043f\u0440\u0438\u0447\u0438\u043d\u0443 \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0439\u0442\u0435 \u0438\u0445 \u0440\u0430\u043d\u044c\u0448\u0435 <code>frontIssue</code>/<code>backIssue</code> \u0438 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0439\u0442\u0435 \u0430\u0434\u0440\u0435\u0441\u043d\u044b\u0439 \u0442\u0435\u043a\u0441\u0442:</p> iOSAndroid <pre><code>let result = try await MergenSDK.verify(front: .image(f), back: .image(b), license: license)\nswitch result.frontOcclusion {\ncase .finger: showError(\"\u041f\u0430\u043b\u0435\u0446 \u0437\u0430\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u0434\u0430\u043d\u043d\u044b\u0435 \u043d\u0430 \u043b\u0438\u0446\u0435\u0432\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u0435 \u2014 \u043f\u0435\u0440\u0435\u0441\u043d\u0438\u043c\u0438\u0442\u0435 \u0435\u0451\")\ncase .shadow: showError(\"\u0422\u0435\u043d\u044c \u0437\u0430\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u0434\u0430\u043d\u043d\u044b\u0435 \u043d\u0430 \u043b\u0438\u0446\u0435\u0432\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u0435 \u2014 \u043f\u0435\u0440\u0435\u0441\u043d\u0438\u043c\u0438\u0442\u0435 \u0435\u0451\")\ncase .none:   break // \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u0439\u0442\u0435 status / frontIssue \u043a\u0430\u043a \u043e\u0431\u044b\u0447\u043d\u043e\n}\n</code></pre> <pre><code>val result = Mergen.verify(context, front, back, license)\nwhen (result.frontOcclusion) {\n    OcclusionType.FINGER -&gt; showError(\"\u041f\u0430\u043b\u0435\u0446 \u0437\u0430\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u0434\u0430\u043d\u043d\u044b\u0435 \u043d\u0430 \u043b\u0438\u0446\u0435\u0432\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u0435 \u2014 \u043f\u0435\u0440\u0435\u0441\u043d\u0438\u043c\u0438\u0442\u0435 \u0435\u0451\")\n    OcclusionType.SHADOW -&gt; showError(\"\u0422\u0435\u043d\u044c \u0437\u0430\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u0434\u0430\u043d\u043d\u044b\u0435 \u043d\u0430 \u043b\u0438\u0446\u0435\u0432\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u0435 \u2014 \u043f\u0435\u0440\u0435\u0441\u043d\u0438\u043c\u0438\u0442\u0435 \u0435\u0451\")\n    OcclusionType.NONE   -&gt; Unit // \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u0439\u0442\u0435 status / frontIssue \u043a\u0430\u043a \u043e\u0431\u044b\u0447\u043d\u043e\n}\n</code></pre> <p>\u0414\u043b\u044f \u0441\u0442\u043e\u0440\u043e\u043d\u044b, \u0441\u043d\u044f\u0442\u043e\u0439 \u0436\u0438\u0432\u043e\u0439 \u043a\u0430\u043c\u0435\u0440\u043e\u0439, \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0432\u0441\u0435\u0433\u0434\u0430 <code>none</code> \u2014 \u0442\u0430\u043c \u043f\u0430\u043b\u0435\u0446 \u0431\u043b\u043e\u043a\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0435\u0449\u0451 \u0432 \u043c\u043e\u043c\u0435\u043d\u0442 \u0441\u044a\u0451\u043c\u043a\u0438 (\u0441\u043c. \u0421\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f \u0441\u043a\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f).</p> <p><code>SameDocumentVerdict</code>:</p> \u0417\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0421\u043c\u044b\u0441\u043b <code>SAME_DOCUMENT</code> \u043e\u0431\u0435 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u043e\u0434\u043d\u043e\u0433\u043e \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430 <code>SAME_WITH_WARNING</code> \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435 \u043f\u0440\u0438 \u043e\u0434\u043d\u043e\u043c \u0441\u043f\u043e\u0440\u043d\u043e\u043c \u0432\u0442\u043e\u0440\u043e\u0441\u0442\u0435\u043f\u0435\u043d\u043d\u043e\u043c \u043f\u043e\u043b\u0435 <code>MISMATCH</code> \u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0440\u0435\u0447\u0438\u044f \u2014 \u0432\u0435\u0440\u043e\u044f\u0442\u043d\u043e, \u0440\u0430\u0437\u043d\u044b\u0435 \u043a\u0430\u0440\u0442\u044b <code>SINGLE_SIDE</code> \u0441\u0432\u0435\u0440\u043a\u0430 \u043f\u043e \u043e\u0434\u043d\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u0435 \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u0430 <code>UNKNOWN</code> \u043d\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u043e"},{"location":"verify.html#_4","title":"\u0412\u044b\u0431\u043e\u0440 \u0444\u043e\u0442\u043e \u0438\u0437 \u0433\u0430\u043b\u0435\u0440\u0435\u0438","text":"<p>\u0413\u043e\u0442\u043e\u0432\u044b\u0435 \u0445\u0435\u043b\u043f\u0435\u0440\u044b, \u0447\u0442\u043e\u0431\u044b \u043d\u0435 \u043f\u0438\u0441\u0430\u0442\u044c \u043e\u0431\u0432\u044f\u0437\u043a\u0443 \u043f\u0438\u043a\u0435\u0440\u043e\u0432:</p> iOSAndroid <pre><code>// SwiftUI-\u043e\u0431\u0451\u0440\u0442\u043a\u0430 \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u043e\u0433\u043e \u043f\u0438\u043a\u0435\u0440\u0430 \u2014 \u0434\u043b\u044f .sheet\nMergenPhotoPicker { image in\n    // image: UIImage? (nil \u2014 \u043e\u0442\u043c\u0435\u043d\u0430); \u0437\u0430\u043a\u0440\u043e\u0439\u0442\u0435 sheet \u0441\u0430\u043c\u0438\n}\n</code></pre> <pre><code>// Compose: \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u044b\u0439 Photo Picker (Android 13+) \u0438\u043b\u0438 GetContent\nval openGallery = rememberMergenGalleryLauncher { bitmap -&gt;\n    // bitmap: Bitmap? (null \u2014 \u043e\u0442\u043c\u0435\u043d\u0430), EXIF-\u043e\u0440\u0438\u0435\u043d\u0442\u0430\u0446\u0438\u044f \u0443\u0436\u0435 \u0438\u0441\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0430\n}\nButton(onClick = openGallery) { Text(\"\u0413\u0430\u043b\u0435\u0440\u0435\u044f\") }\n\n// \u0412\u043d\u0435 Compose: \u0434\u0435\u043a\u043e\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 content-URI \u0441 EXIF-\u043a\u043e\u0440\u0440\u0435\u043a\u0446\u0438\u0435\u0439\nval bitmap: Bitmap? = Mergen.decodeImage(context, uri)\n</code></pre> <p>\u041f\u043e\u043b\u0443\u0447\u0435\u043d\u043d\u043e\u0435 \u0438\u0437\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u0435 \u043f\u0435\u0440\u0435\u0434\u0430\u0451\u0442\u0441\u044f \u0432 <code>verify</code> \u043a\u0430\u043a <code>.image(...)</code>. \u041d\u0430 \u044d\u043a\u0440\u0430\u043d\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0439\u0442\u0435 <code>frontPhoto</code> / <code>backPhoto</code> \u0438\u0437 \u0432\u0435\u0440\u0434\u0438\u043a\u0442\u0430 \u2014 \u044d\u0442\u043e \u0432\u044b\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u0430\u044f \u043a\u0430\u0440\u0442\u0430, \u0430 \u043d\u0435 \u0438\u0441\u0445\u043e\u0434\u043d\u043e\u0435 \u0444\u043e\u0442\u043e \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f.</p>"},{"location":"verify.html#_5","title":"\u041e\u0448\u0438\u0431\u043a\u0438","text":"iOSAndroid <pre><code>catch {\n    let text = (error as? MergenError)?.userMessage ?? error.localizedDescription\n}\n</code></pre> <p><code>MergenError</code>: <code>.licenseEmpty</code>, <code>.engineInitFailed</code>, <code>.cameraPermissionDenied</code> \u2014 \u0443 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0433\u043e\u0442\u043e\u0432\u044b\u0439 \u0440\u0443\u0441\u0441\u043a\u0438\u0439 <code>userMessage</code>.</p> <pre><code>catch (e: Exception) {\n    val text = (e as? MergenException)?.userMessage ?: e.localizedMessage\n}\n</code></pre> <p><code>MergenException</code> \u2014 \u0438\u043d\u0442\u0435\u0440\u0444\u0435\u0439\u0441 \u0441 \u0433\u043e\u0442\u043e\u0432\u044b\u043c \u0440\u0443\u0441\u0441\u043a\u0438\u043c <code>userMessage</code>; \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438: <code>CameraPermissionDeniedException</code>, <code>UnsupportedAbiException</code> (\u0441 \u043f\u043e\u043b\u044f\u043c\u0438 <code>deviceAbis</code> / <code>supportedAbis</code>). \u041f\u0443\u0441\u0442\u0430\u044f \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u044f \u2014 <code>IllegalStateException</code>, \u0441\u0431\u043e\u0439 \u0438\u043d\u0438\u0446\u0438\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u0434\u0432\u0438\u0436\u043a\u0430 \u2014 <code>RuntimeException</code>.</p>"}]}